window.CC.p.push({n:10,view:"<section class=\"view\" id=\"p10\" hidden style=\"--c:#6a3fb5\"><h1><i>10</i>Neurology &amp; Psychiatry</h1><p class=\"lead\">30 sections — pick what you want to read.</p><div class=\"grid\"><h3 class=\"sg\">Part 10A</h3><div class=\"card\" data-u=\"u233\"><button class=\"open\" data-u=\"u233\"><b>Case 1</b><span>Acute Ischemic Stroke &amp; Transient Ischemic Attack (TIA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Ischemic+Stroke+%26+Transient+Ischemic+Attack+%28TIA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u234\"><button class=\"open\" data-u=\"u234\"><b>Case 2</b><span>Intracerebral Hemorrhage (ICH)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Intracerebral+Hemorrhage+%28ICH%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u235\"><button class=\"open\" data-u=\"u235\"><b>Case 3</b><span>Subarachnoid Hemorrhage (SAH)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Subarachnoid+Hemorrhage+%28SAH%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u236\"><button class=\"open\" data-u=\"u236\"><b>Case 4</b><span>Epilepsy &amp; Adult Status Epilepticus</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Epilepsy+%26+Adult+Status+Epilepticus\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u237\"><button class=\"open\" data-u=\"u237\"><b>Case 5</b><span>Migraine Headache (ACUTE &amp; PREVENTIVE)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Migraine+Headache+%28ACUTE+%26+PREVENTIVE%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u238\"><button class=\"open\" data-u=\"u238\"><b>Case 6</b><span>Tension-Type Headache &amp; Cluster Headache</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Tension-Type+Headache+%26+Cluster+Headache\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u239\"><button class=\"open\" data-u=\"u239\"><b>Case 7</b><span>Idiopathic Intracranial Hypertension (IIH) &amp; Giant Cell Arteritis (GCA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Idiopathic+Intracranial+Hypertension+%28IIH%29+%26+Giant+Cell+Arteritis+%28GCA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u240\"><button class=\"open\" data-u=\"u240\"><b>Case 8</b><span>Parkinsonʼs Disease &amp; Essential Tremor</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Parkinson%CA%BCs+Disease+%26+Essential+Tremor\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u241\"><button class=\"open\" data-u=\"u241\"><b>Case 9</b><span>Dementia &amp; Major Neurocognitive Disorders (DIFFERENTIATION)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Dementia+%26+Major+Neurocognitive+Disorders+%28DIFFERENTIATION%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u242\"><button class=\"open\" data-u=\"u242\"><b>Case 10</b><span>Multiple Sclerosis (MS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Multiple+Sclerosis+%28MS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u243\"><button class=\"open\" data-u=\"u243\"><b>Case 11</b><span>Guillain-Barré Syndrome (GBS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Guillain-Barr%C3%A9+Syndrome+%28GBS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u244\"><button class=\"open\" data-u=\"u244\"><b>Case 12</b><span>Myasthenia Gravis (MG) &amp; Myasthenic Crisis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Myasthenia+Gravis+%28MG%29+%26+Myasthenic+Crisis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u245\"><button class=\"open\" data-u=\"u245\"><b>Case 13</b><span>Peripheral Neuropathy &amp; Carpal Tunnel Syndrome</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Peripheral+Neuropathy+%26+Carpal+Tunnel+Syndrome\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u246\"><button class=\"open\" data-u=\"u246\"><b>Case 14</b><span>Lumbar Disc Herniation (SCIATICA) &amp; Cauda Equina Syndrome</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Lumbar+Disc+Herniation+%28SCIATICA%29+%26+Cauda+Equina+Syndrome\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u247\"><button class=\"open\" data-u=\"u247\"><b>Case 15</b><span>Trigeminal Neuralgia &amp; Amyotrophic Lateral Sclerosis (ALS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Trigeminal+Neuralgia+%26+Amyotrophic+Lateral+Sclerosis+%28ALS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><h3 class=\"sg\">Part 10B</h3><div class=\"card\" data-u=\"u248\"><button class=\"open\" data-u=\"u248\"><b>Case 16</b><span>Major Depressive Disorder (MDD) &amp; Suicide Risk Assessment</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Major+Depressive+Disorder+%28MDD%29+%26+Suicide+Risk+Assessment\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u249\"><button class=\"open\" data-u=\"u249\"><b>Case 17</b><span>Bipolar I &amp; II Disorder (ACUTE MANIA &amp; MAINTENANCE)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Bipolar+I+%26+II+Disorder+%28ACUTE+MANIA+%26+MAINTENANCE%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u250\"><button class=\"open\" data-u=\"u250\"><b>Case 18</b><span>Generalized Anxiety Disorder (GAD) &amp; Panic Disorder</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Generalized+Anxiety+Disorder+%28GAD%29+%26+Panic+Disorder\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u251\"><button class=\"open\" data-u=\"u251\"><b>Case 19</b><span>Obsessive-Compulsive Disorder (OCD) &amp; PTSD</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Obsessive-Compulsive+Disorder+%28OCD%29+%26+PTSD\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u252\"><button class=\"open\" data-u=\"u252\"><b>Case 20</b><span>Schizophrenia &amp; Acute Psychosis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Schizophrenia+%26+Acute+Psychosis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u253\"><button class=\"open\" data-u=\"u253\"><b>Case 21</b><span>Delirium vs. Dementia (HOSPITAL CONFUSION APPROACH)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Delirium+vs.+Dementia+%28HOSPITAL+CONFUSION+APPROACH%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u254\"><button class=\"open\" data-u=\"u254\"><b>Case 22</b><span>Alcohol Withdrawal Syndrome, Delirium Tremens &amp; Wernicke-Korsakoff</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Alcohol+Withdrawal+Syndrome%2C+Delirium+Tremens+%26+Wernicke-Korsakoff\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u255\"><button class=\"open\" data-u=\"u255\"><b>Case 23</b><span>Opioid Overdose/withdrawal &amp; Tramadol / Benzodiazepine Misuse</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Opioid+Overdose%2Fwithdrawal+%26+Tramadol+%2F+Benzodiazepine+Misuse\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u256\"><button class=\"open\" data-u=\"u256\"><b>Case 24</b><span>Serotonin Syndrome vs. Neuroleptic Malignant Syndrome (NMS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Serotonin+Syndrome+vs.+Neuroleptic+Malignant+Syndrome+%28NMS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u257\"><button class=\"open\" data-u=\"u257\"><b>Case 25</b><span>Somatic Symptom, Illness Anxiety &amp; Functional Neurological Disorder</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Somatic+Symptom%2C+Illness+Anxiety+%26+Functional+Neurological+Disorder\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u258\"><button class=\"open\" data-u=\"u258\"><b>Case 26</b><span>Eating Disorders (ANOREXIA NERVOSA &amp; BULIMIA NERVOSA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Eating+Disorders+%28ANOREXIA+NERVOSA+%26+BULIMIA+NERVOSA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u259\"><button class=\"open\" data-u=\"u259\"><b>Case 27</b><span>ADHD &amp; Autism Spectrum Disorder (CHILD &amp; ADOLESCENT PSYCHIATRY)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=ADHD+%26+Autism+Spectrum+Disorder+%28CHILD+%26+ADOLESCENT+PSYCHIATRY%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u260\"><button class=\"open\" data-u=\"u260\"><b>Case 28</b><span>Insomnia Disorder &amp; Parasomnias</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Insomnia+Disorder+%26+Parasomnias\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u261\"><button class=\"open\" data-u=\"u261\"><b>Case 29</b><span>Psychotropic Drug Toxicities &amp; Side Effects Mastery</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Psychotropic+Drug+Toxicities+%26+Side+Effects+Mastery\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u262\"><button class=\"open\" data-u=\"u262\"><b>Case 30</b><span>Altered Mental Status (&quot;AEIOU-TIPS&quot;) ER Approach &amp; Brain Death</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Altered+Mental+Status+%28%22AEIOU-TIPS%22%29+ER+Approach+%26+Brain+Death\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div></div></section>",units:"<article class=\"view unit\" id=\"u233\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 1</span><h1>Acute Ischemic Stroke &amp; Transient Ischemic Attack (TIA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Ischemic+Stroke+%26+Transient+Ischemic+Attack+%28TIA%29\">🔍 Search on Google</a></header><h3><b>1. Definitions</b></h3><ul>\n<li class=\"l1\"><b>Acute Ischemic Stroke:</b> Sudden-onset focal neurological deficit lasting <b>≥ 24 hours</b> (or showing acute infarction on neuroimaging) due to cerebral arterial occlusion.</li>\n<li class=\"l1\"><b>TIA</b> (Transient Ischemic Attack): Transient episode of neurological dysfunction caused by focal brain, spinal cord, or retinal ischemia <mark class=\"hl mech\"><b>WITHOUT acute infarction on MRI</b></mark> (Magnetic Resonance Imaging) — typically resolving within &lt; 1 hour! <b>A TIA is a massive warning sign for an impending full stroke within 48 hours!</b></li>\n</ul><h3><b>2. Etiology (Separated by Mechanism)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl dx\"><b>Large-Artery Atherosclerosis (~20–30%):</b></mark> Plaque rupture/stenosis at the carotid bifurcation or intracranial arteries (risk factors: <b>HTN</b> [Hypertension], <b>DM </b>[Diabetes Mellitus], smoking, dyslipidemia).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Cardioembolism (~25–30%):</b> <mark class=\"hl lab\"><b>Atrial Fibrillation (AFib — #1!)</b></mark> , recent <mark class=\"hl lab\"><b>MI</b></mark> (Myocardial Infarction) mural thrombus, <b>RHD</b> (Rheumatic Heart Disease — Mitral Stenosis, very common in Egypt!), Infective endocarditis, Prosthetic valves.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Small-Vessel Occlusion (\"Lacunar Strokes\" ~20–25%):</b> Lipohyalinosis of deep penetrating lenticulostriate arteries due to chronic <b>HTN</b> &amp; <b>DM</b> (causes pure motor hemiparesis, pure sensory stroke, or dysarthria-clumsy hand).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Other / Cryptogenic (~15–20%):</b> Carotid/vertebral <b>arterial dissection</b> (young patients after neck trauma/chiropractic manipulation + Horner’s syndrome!), <mark class=\"hl lab\"><b>APS </b></mark>(Antiphospholipid Syndrome), Sickle cell disease, Patent Foramen Ovale (paradoxical embolism).</span></p><h3><b>3. Clinical Picture (Vascular Territory Localization)</b></h3><ul>\n<li class=\"l1\"><b>MCA</b> (Middle Cerebral Artery — #1 Overall): Contralateral face &amp; arm weakness/sensory loss (<b>Face/Arm &gt; Leg</b>), contralateral homonymous hemianopia, <b>Aphasia</b> if dominant (left) hemisphere (<b>Broca’s</b> = non-fluent expressive; <b>Wernicke’s</b> = fluent nonsensical receptive), <b>Hemineglect</b> if non-dominant (right).</li>\n<li class=\"l1\"><b>ACA</b> (Anterior Cerebral Artery): Contralateral <b>Leg &gt; Arm/Face</b> weakness &amp; sensory loss, abulia, urinary incontinence.</li>\n<li class=\"l1\"><b>PCA</b> (Posterior Cerebral Artery): Contralateral homonymous hemianopia with <b>macular sparing</b>.</li>\n<li class=\"l1\"><b>Brainstem / Vertebrobasilar (\"Crossed Signs\"):</b> Ipsilateral cranial nerve palsy + contralateral body weakness/sensory loss + <b>\"4 Ds\"</b> (Diplopia, Dysarthria, Dysphagia, Dizziness/Ataxia).</li>\n</ul><h3><b>4. Investigations (\"Time Is Brain!\" — STAT ER Protocol)</b></h3><ul>\n<li class=\"l1\"><b>Immediate Fingerstick Blood Glucose</b> (MANDATORY to rule out <b>Hypoglycemia</b>, the #1 stroke mimic!).</li>\n<li class=\"l1\"><b>STAT Non-Contrast CT</b> (Computed Tomography) <b>Brain (Within ≤ 20–25 Minutes!):</b> Purpose is to <b>EXCLUDE Intracerebral Hemorrhage</b> before thrombolysis <i>(early ischemic stroke CT is often NORMAL within first 6–12 hrs!)</i>.</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>CT Angiography (CTA) Head &amp; Neck:</b></mark> Identifies <b>Large Vessel Occlusion (LVO)</b> for thrombectomy!</li>\n<li class=\"l1\"><b>Secondary Prevention Workup (After stabilization):</b> <mark class=\"hl mech\"><b>MRI Brain (DWI</b></mark> [Diffusion-Weighted Imaging]), <mark class=\"hl mech\"><b>12-Lead ECG</b></mark> (Electrocardiogram) + Telemetry (<mark class=\"hl lab\"><b> rule out AFib!</b></mark> ), <mark class=\"hl mech\"><b>Transthoracic Echocardiogram</b></mark> , <b>Carotid Duplex Ultrasound</b>, <mark class=\"hl mech\"><b>HbA1c</b></mark> , Lipid Profile.</li>\n</ul><h3><b>5. Differential Diagnosis (DDx — Stroke Mimics)</b></h3><ul>\n<li class=\"l1\"><b>Hypoglycemia</b>, Post-ictal (<b>Todd’s</b>) paralysis, Hemiplegic migraine, Functional/Conversion disorder, Brain tumor/abscess, Hypertensive encephalopathy, Bell’s palsy (isolated peripheral CN VII!).</li>\n</ul><h3><b>6. Complications</b></h3><ul>\n<li class=\"l1\">Malignant cerebral edema &amp; herniation (Days 2–5), Hemorrhagic transformation, Aspiration pneumonia, <mark class=\"hl lab\"><b>DVT/PE</b></mark> (Deep Vein Thrombosis / Pulmonary Embolism), Post-stroke seizures, Depression.</li>\n</ul><h3><b>7. Treatment (Acute Reperfusion + Secondary Prevention)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl rx\"><b>IV Thrombolysis — Alteplase (tPA) or Tenecteplase:</b></mark></span></p>\n<ul>\n<li class=\"l2\">Give within <b>4.5 hours of \"Last Known Well\"</b> time!</li>\n<li class=\"l2\"><i>Pre-tPA BP Target:</i> Must lower BP to <b>&lt; 185/110 mmHg</b> using <mark class=\"hl rx\"><b>IV Labetalol</b></mark> or <b>Nicardipine</b> before starting tPA (and maintain <b>&lt; 180/105 mmHg</b> for 24 hrs!).</li>\n<li class=\"l2\"><i>Key Contraindications:</i> Any intracranial bleed on CT, prior ICH, ischemic stroke/head trauma/major surgery &lt; 3 months, active internal bleed, Platelets &lt; 100,000, <mark class=\"hl mech\"><b>INR &gt; 1.7</b></mark> or recent <b>DOAC</b> (&lt; 48 hrs).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Mechanical Endovascular Thrombectomy:</b> For <b>Large Vessel Occlusion (LVO — ICA/M1)</b> up to <b>6–24 hours</b> (if salvageable penumbra on CT perfusion/MRI!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl rx\"><b>If NOT a Candidate for tPA:</b></mark></span></p>\n<ul>\n<li class=\"l2\"><b>Permissive Hypertension:</b> <b>DO NOT lower BP unless &gt; 220/120 mmHg</b> during the first 24–48 hrs (aggressive BP lowering destroys ischemic penumbra!).</li>\n<li class=\"l2\"><b>Antiplatelets:</b> Start <mark class=\"hl rx\"><b>Aspirin 160–325 mg</b></mark> within 24–48 hrs (<i>wait 24 hrs + repeat CT if patient received tPA!</i>). For <b>minor stroke (NIHSS ≤ 3) or high-risk TIA (ABCD2 ≥ 4)</b>: give <mark class=\"hl rx\"><b>Short-Term DAPT (Aspirin + Clopidogrel) for 21 days</b></mark> , then monotherapy!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Long-Term Secondary Prevention:</b> High-intensity <mark class=\"hl rx\"><b>Statin</b></mark> (Atorvastatin 40–80 mg), gradual BP control (&lt; 130/80), <mark class=\"hl rx\"><b>Anticoagulation (DOAC or Warfarin)</b></mark> if <mark class=\"hl lab\"><b>AFib </b></mark>(start 4–14 days post-stroke depending on infarct size!), <b>Carotid Endarterectomy (CEA)</b> for symptomatic 70–99% internal carotid stenosis!</span></p><nav class=\"un\"><span></span><button class=\"nv\" data-u=\"u234\">Case 2 →</button></nav></article><article class=\"view unit\" id=\"u234\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 2</span><h1>Intracerebral Hemorrhage (ICH)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Intracerebral+Hemorrhage+%28ICH%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Spontaneous bleeding directly into the brain parenchyma (~10–15% of all strokes, carrying <b>highest early mortality</b>!).</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Chronic Hypertension (#1 Cause Overall!):</b> Rupture of tiny <b>Charcot-Bouchard microaneurysms</b> on penetrating arteries -&gt; classic locations: <b>Basal Ganglia (Putamen — #1!)</b>, <b>Thalamus</b>, <b>Pons</b>, and <b>Cerebellum</b>!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Cerebral Amyloid Angiopathy (#1 Cause in Normotensive Elderly &gt; 60–70 Yrs):</b> <b>Lobar hemorrhages</b> (parietal/occipital) from β-amyloid weakening cortical vessels!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Coagulopathy / Medications:</b> <mark class=\"hl rx\"><b>Warfarin / DOACs</b></mark> , Thrombolytics, Thrombocytopenia, Liver failure.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Structural / Vascular (Suspect in Young Normotensive Patients!):</b> <b>AVM</b> (Arteriovenous Malformation), Cavernoma, <b>Cocaine/Amphetamines</b>, Hemorrhagic transformation of ischemic stroke, Brain tumor hemorrhage (Melanoma/RCC/Choriocarcinoma).</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Sudden-onset focal neurological deficit that <b>progresses smoothly over minutes to hours</b>, accompanied by <b>severe headache, vomiting, markedly elevated BP, and rapidly declining level of consciousness</b>!</li>\n<li class=\"l1\"><i>Classic Localization Clues:</i> <b>Putamen</b> = contralateral hemiplegia + eyes look <i>toward</i> lesion; <b>Pons</b> = coma + <b>pinpoint reactive pupils</b> + quadriplegia; <b>Cerebellum</b> = occipital headache + vomiting + ataxia + <b>high risk of sudden brainstem compression</b>!</li>\n</ul><h3><b>4. Investigations &amp; Emergency Treatment</b></h3><ul>\n<li class=\"l1\"><b>STAT Non-Contrast CT Brain:</b> Immediately confirms <b>bright white (hyperdense) intraparenchymal blood</b> +/- intraventricular extension or midline shift! <i>(CTA if young/lobar to find AVM!).</i></li>\n<li class=\"l1\"><b>Treatment:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Airway &amp; ICP Control:</b> Intubate if GCS ≤ 8; head of bed 30°; <mark class=\"hl rx\"><b>Mannitol / 3% Hypertonic Saline</b></mark> if herniation signs.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Careful BP Reduction:</b> Lower <mark class=\"hl lab\"><b>SBP smoothly to ~140 mmHg</b></mark> using titratable <mark class=\"hl rx\"><b>IV Nicardipine or Labetalol</b></mark> (unlike ischemic stroke, lowering severe HTN reduces hematoma expansion!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>IMMEDIATE REVERSAL OF ANTICOAGULANTS (CRITICAL!):</b></span></p>\n<ul>\n<li class=\"l1\"><i>Warfarin:</i> <b>4-Factor PCC</b> (Prothrombin Complex Concentrate) <b>+ IV Vitamin K 10 mg</b>!</li>\n<li class=\"l1\"><i>Dabigatran:</i> <b>Idarucizumab</b> | <i>Apixaban/Rivaroxaban:</i> <b>Andexanet alfa</b> (or 4-Factor PCC) | <i>Heparin:</i> <b>Protamine Sulfate</b>.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Emergent Neurosurgery:</b> Indicated immediately for <b>Cerebellar Hemorrhage &gt; 3 cm</b> (or with brainstem compression/hydrocephalus — <b>life-saving decompression!</b>) or external ventricular drain (<b>EVD</b>) for hydrocephalus!</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u233\">← Case 1</button><button class=\"nv\" data-u=\"u235\">Case 3 →</button></nav></article><article class=\"view unit\" id=\"u235\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 3</span><h1>Subarachnoid Hemorrhage (SAH)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Subarachnoid+Hemorrhage+%28SAH%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Extravasation of arterial blood into the <b>subarachnoid space</b> between the arachnoid and pia mater.</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Trauma (#1 Cause Overall).</b></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Ruptured Saccular (\"Berry\") Aneurysm (~80–85% of Non-Traumatic Spontaneous SAH):</b></mark> Most commonly at the <b>Anterior Communicating Artery (ACom)</b>, Posterior Communicating Artery (<b>PCom — causes painful CN III palsy with dilated pupil!</b>), or <b>MCA</b> bifurcation. <i>(Associated with </i><i><b>ADPKD</b></i><i> [Autosomal Dominant Polycystic Kidney Disease], Smoking, HTN, Ehlers-Danlos, Coarctation of Aorta).</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl lab\"><b>AVM (~10%) &amp; Perimesencephalic Non-Aneurysmal SAH (~5–10%).</b></mark></span></p><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ 3. Clinical Picture (THE RED FLAG HEADACHE!)</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><b>\"Thunderclap\" Headache:</b> Sudden-onset, explosive headache reaching <b>maximal intensity within seconds</b> (<i>\"Worst headache of my life!\"</i>) — often during exertion/straining/intercourse!</li>\n<li class=\"l1\">Brief loss of consciousness, nausea/vomiting, photophobia, <b>meningismus (neck stiffness)</b>, <b>subhyaloid retinal hemorrhages (Terson’s syndrome)</b>, or <b>CN III palsy</b> (PCom aneurysm!).</li>\n</ul></div></div><h3><b>4. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Step 1 — STAT Non-Contrast CT Brain:</b> Hyperdense blood filling the basal cisterns/Sylvian fissures (~95–100% sensitive within first 6 hours!).</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Step 2 — Lumbar Puncture (MANDATORY ONLY if CT is Negative/Equivocal despite high clinical suspicion!):</b></mark> Look for <mark class=\"hl mech\"><b>Xanthochromia</b></mark> (yellowish CSF supernatant from bilirubin breakdown — peaks at 12 hrs!) and persistently elevated <b>RBCs</b> across Tubes 1 and 4!</li>\n<li class=\"l1\"><b>Step 3 — CTA Brain / Digital Subtraction Angiography (DSA — Gold Standard):</b> Identifies exact aneurysm!</li>\n<li class=\"l1\"><b>Complications &amp; Specific Management:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Rebleeding (Highest in first 24 hrs!):</b> <b>Urgent Endovascular Coiling (preferred) or Surgical Clipping within 24–72 hrs</b> + strict BP control (SBP &lt; 140–160 mmHg before securing aneurysm) + <b>NO antiplatelets/anticoagulants</b>!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Cerebral Vasospasm &amp; Delayed Ischemia (Days 4–14):</b> Prevented with <b>Oral Nimodipine (60 mg q4h for 21 days)</b> — <b>ONLY drug proven to improve neurological outcome!</b> (Monitor with daily <b>Transcranial Doppler</b>!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Acute Hydrocephalus</b> (blood blocks arachnoid villi -&gt; <b>EVD</b>) &amp; <b>Hyponatremia</b> (SIADH / Cerebral Salt Wasting).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u234\">← Case 2</button><button class=\"nv\" data-u=\"u236\">Case 4 →</button></nav></article><article class=\"view unit\" id=\"u236\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 4</span><h1>Epilepsy &amp; Adult Status Epilepticus</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Epilepsy+%26+Adult+Status+Epilepticus\">🔍 Search on Google</a></header><h3><b>1. Definitions</b></h3><ul>\n<li class=\"l1\"><b>Seizure:</b> Transient clinical event caused by abnormal, excessive, hypersynchronous cortical neuronal discharge.</li>\n<li class=\"l1\"><b>Epilepsy:</b> Tendency for recurrent unprovoked seizures (<b>≥ 2 unprovoked seizures &gt; 24 hrs apart</b>, OR <b>1 unprovoked seizure with ≥ 60% recurrence risk</b>).</li>\n<li class=\"l1\"><b>Status Epilepticus (SE):</b> Continuous seizure activity lasting <b>≥ 5 minutes</b> OR <b>≥ 2 sequential seizures without full recovery of consciousness in between</b>! (<b>NEUROLOGICAL EMERGENCY!</b>)</li>\n</ul><h3><b>2. Etiology (Separated by Age — Provoked vs. Unprovoked)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Acute Provoked Causes (Correct the Cause — Do NOT Diagnose Epilepsy!):</b> <b>Hypoglycemia</b>, <b>Hyponatremia / Hypocalcemia</b>, Alcohol/Benzodiazepine withdrawal, Drug intoxication (Tramadol — <i>very common in Egypt!</i> — Cocaine, Theophylline, Isoniazid), Fever/Meningitis/Encephalitis, <mark class=\"hl lab\"><b>Eclampsia</b></mark> , Uremia/Hepatic encephalopathy.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Unprovoked / Structural Causes:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Children/Adolescents:</i> Genetic/Idiopathic generalized syndromes (Absence, <b>JME</b> [Juvenile Myoclonic Epilepsy — morning myoclonic jerks!]), Febrile seizures, Congenital malformations.</li>\n<li class=\"l2\"><i>Adults/Elderly:</i> <b>Prior Stroke (#1 cause in elderly!)</b>, <b>Brain Tumors</b>, Head trauma, Mesial temporal sclerosis (Temporal Lobe Epilepsy — rising epigastric aura, automatisms!).</li>\n</ul><h3><b>3. Investigations</b></h3><ul>\n<li class=\"l1\"><b>First-Ever Seizure Workup:</b> <b>Fingerstick Glucose</b>, <b>Electrolytes (Na+, Ca++, Mg++)</b>, <mark class=\"hl mech\"><b>RFTs/LFTs</b></mark> , <b>Urine Drug Screen</b>, <b>Pregnancy Test</b>, <mark class=\"hl mech\"><b>CT/MRI Brain</b></mark> (preferred in non-emergent structural evaluation), and <mark class=\"hl mech\"><b>EEG</b></mark> (Electroencephalogram — <i>normal interictal EEG does NOT rule out epilepsy!</i>).</li>\n</ul><h3><b>4. Treatment (Chronic Antiseizure Medications [ASMs] + Status Epilepticus Protocol)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Long-Term ASMs (Tailor to Seizure Type &amp; Patient — Wait for ≥ 2nd Unprovoked Seizure unless abnormal MRI/EEG!):</b></mark></li>\n<li class=\"l2\"><i>Focal-Onset Seizures:</i> <b>Levetiracetam</b> (cleanest side-effect profile!), <b>Lamotrigine</b>, <b>Carbamazepine / Oxcarbazepine</b> (<i>check HLA-B</i>1502 in East Asians; causes hyponatremia!*).</li>\n<li class=\"l2\"><i>Generalized Tonic-Clonic:</i> <b>Levetiracetam</b>, <b>Lamotrigine</b>, <b>Valproate</b> (<i>AVOID Valproate in women of childbearing age due to severe teratogenicity [neural tube defects/autism] and PCOS!</i>).</li>\n<li class=\"l2\"><i>Absence Seizures (\"Staring spells\" with 3-Hz spike-and-wave EEG):</i> <b>Ethosuximide</b> (first-line for pure absence!) or Valproate/Lamotrigine (<i>Carbamazepine/Phenytoin WORSEN absence &amp; JME!</i>).</li>\n<li class=\"l1\"><b>ADULT STATUS EPILEPTICUS PROTOCOL:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>0–5 Min (Stabilize):</b> Airway/O2, IV access, <b>CHECK GLUCOSE</b> (if low or unknown -&gt; <mark class=\"hl rx\"><b>IV Thiamine 100 mg + 50 mL D50W</b></mark> !).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>5–10 Min (1st-Line Benzodiazepine):</b> <b>IV Lorazepam 4 mg (0.1 mg/kg)</b> OR <b>IV Diazepam 10 mg</b> (if no IV -&gt; <b>IM Midazolam 10 mg</b>!). Repeat once in 5 min if still seizing.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>20 Min (2nd-Line — Load 1 Drug):</b> <b>IV Levetiracetam (60 mg/kg, max 4,500 mg)</b> OR <b>IV Fosphenytoin/Phenytoin (20 mg/kg)</b> OR <b>IV Valproate (40 mg/kg)</b>.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>40+ Min (Refractory SE):</b> ICU Intubation + Continuous <b>IV Midazolam, Propofol, or Ketamine/Pentobarbital</b> infusion under continuous EEG monitoring!</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u235\">← Case 3</button><button class=\"nv\" data-u=\"u237\">Case 5 →</button></nav></article><article class=\"view unit\" id=\"u237\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 5</span><h1>Migraine Headache (ACUTE &amp; PREVENTIVE)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Migraine+Headache+%28ACUTE+%26+PREVENTIVE%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Common, disabling primary neurovascular headache disorder characterized by recurrent moderate-to-severe unilateral throbbing headaches associated with autonomic/sensory hypersensitivity. <b>3:1 Female predominance.</b></p><h3><b>2. Pathophysiology &amp; Triggers</b></h3><ul>\n<li class=\"l1\"><b>Pathophysiology:</b> Cortical spreading depression (causes aura) + <b>trigeminovascular activation</b> releasing <b>CGRP</b> (Calcitonin Gene-Related Peptide) -&gt; neurogenic dural inflammation and vasodilation.</li>\n<li class=\"l1\"><b>Triggers:</b> Menstrual estrogen drops, stress/let-down, missed meals/fasting (<i>Ramadan headaches!</i>), sleep disruption, bright lights, aged cheese/chocolate/caffeine withdrawal.</li>\n</ul><h3><b>3. Clinical Picture (Duration: 4–72 Hours Untreated)</b></h3><ul>\n<li class=\"l1\"><b>Classic Features:</b> <b>Unilateral</b> (can be bilateral in ~30–40%), <b>pulsatile/throbbing</b>, moderate-to-severe intensity, <b>worsened by routine physical activity</b> (patient prefers lying in a <b>dark quiet room</b>!), accompanied by <b>Nausea/Vomiting</b> and <b>Photophobia + Phonophobia</b>.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Migraine WITH Aura (~25%):</b></mark> Reversible visual symptoms (<b>scintillating scotomas, zig-zag fortification spectra</b>) or sensory tingling developing gradually over 5– 20 min and lasting <b>&lt; 60 minutes</b> before headache!</li>\n<li class=\"l1\"><i>CRITICAL RULE:</i> Women with <mark class=\"hl lab\"><b>Migraine WITH Aura</b></mark> have <b>WHO Category 4 Contraindication to Estrogen-containing COCs</b> (Combined Oral Contraceptives) due to elevated <b>Ischemic Stroke risk</b>!</li>\n</ul><h3><b>4. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Acute Abortive Therapy (Take at EARLIEST onset! Limit to &lt; 10 days/month to prevent Medication-Overuse Headache!):</b></li>\n<li class=\"l2\"><i>Mild-Moderate:</i> <mark class=\"hl rx\"><b>NSAIDs</b></mark> (Ibuprofen 400–800 mg, Naproxen 500 mg) or Acetaminophen + <b>Antiemetic</b> (Metoclopramide — also enhances absorption!).</li>\n<li class=\"l2\"><i>Moderate-Severe / Failed NSAIDs:</i> <b>Triptans</b> (<b>Sumatriptan</b> 50–100 mg PO or 6 mg SC, Rizatriptan, Zolmitriptan — 5-HT1B/1D agonists!). <i>CONTRAINDICATIONS to Triptans:</i> <mark class=\"hl lab\"><b>CAD, Uncontrolled HTN, Stroke/TIA, Peripheral Vascular Disease, Basilar/Hemiplegic migraine!</b></mark></li>\n<li class=\"l2\"><i>If Triptans Contraindicated:</i> <b>Gepants</b> (Rimegepant, Ubrogepant — CGRP antagonists!).</li>\n<li class=\"l2\"><i>ER Status Migrainosus (&gt; 72 hrs):</i> <mark class=\"hl rx\"><b>IV Fluids + IV Metoclopramide (or Prochlorperazine) + IV Ketorolac + IV Magnesium Sulfate +/- IV Dexamethasone </b></mark>(reduces recurrence!). Avoid opioids!</li>\n<li class=\"l1\"><b>Preventive Therapy (Indicated if ≥ 4 headache days/month or disabling attacks):</b></li>\n<li class=\"l2\"><b>Beta-Blockers</b> (<mark class=\"hl rx\"><b> Propranolol</b></mark> , Metoprolol — avoid in asthma!).</li>\n<li class=\"l2\"><b>TCAs</b> (Tricyclic Antidepressants — <b>Amitriptyline</b> 10–50 mg at night — great if comorbid insomnia/tension!).</li>\n<li class=\"l2\"><b>Anticonvulsants:</b> <b>Topiramate</b> (causes weight loss, paresthesia, kidney stones — teratogenic!) or <b>Valproate</b> (avoid in women of childbearing age!).</li>\n<li class=\"l2\"><b>CGRP Monoclonal Antibodies</b> (Erenumab, Fremanezumab, Galcanezumab) or <b>OnabotulinumtoxinA</b> (for Chronic Migraine ≥ 15 days/month).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u236\">← Case 4</button><button class=\"nv\" data-u=\"u238\">Case 6 →</button></nav></article><article class=\"view unit\" id=\"u238\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 6</span><h1>Tension-Type Headache &amp; Cluster Headache</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Tension-Type+Headache+%26+Cluster+Headache\">🔍 Search on Google</a></header><h4><b>High-Yield Primary Headache Comparison</b></h4><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Tension-Type Headache </b><i><b>(#1 Most Common!)</b></i></p></th><th><p><mark class=\"hl lab\"><b>Cluster Headache </b></mark><i><b>(Trigeminal Autonomic Cephalalgia)</b></i></p></th></tr><tr><td><p><b>Typical Patient</b></p></td><td><p>Adults (slight female predominance); stress/fatigue</p></td><td><p><b>Young-to-middle-aged MALE SMOKERS (4:1 M:F!)</b></p></td></tr><tr><td><p><b>Location &amp; Quality</b></p></td><td><p><b>Bilateral \"Band-like / Vice-like\"</b> squeezing pressure around forehead/occiput</p></td><td><p><b>Strictly UNILATERAL excruciating boring/stabbing pain</b> behind/around <b>ONE EYE</b>!</p></td></tr><tr><td><p><b>Duration &amp; Timing</b></p></td><td><p>30 min – 7 days; worsens later in day</p></td><td><p><b>15 – 180 minutes</b>; occurs in <b>\"clusters\"</b> (1–8×/day for weeks, often <b>waking patient at the exact same time every night!</b>)</p></td></tr><tr><td><p><b>Associated Features</b></p></td><td><p>Mild pericranial muscle tenderness; <b>NO nausea/vomiting, NO photophobia + phonophobia</b>; NOT worsened by activity</p></td><td><p><b>Ipsilateral Autonomic Signs:</b> <b>Red tearing eye (lacrimation), nasal congestion/rhinorrhea, ptosis/miosis (partial Horner’s)</b> + <b>extreme restlessness/pacing</b> (unlike migraine!)</p></td></tr><tr><td><p><b>Acute Treatment</b></p></td><td><p><mark class=\"hl rx\"><b>NSAIDs / Acetaminophen</b></mark> , stress/sleep hygiene</p></td><td><p><b>100% High-Flow Oxygen (12–15 L/min via Non-Rebreather Mask × 15 min — FIRST-LINE!)</b> + <b>Subcutaneous Sumatriptan 6 mg</b>!</p></td></tr><tr><td><p><b>Preventive Therapy</b></p></td><td><p><b>Amitriptyline</b> (if chronic)</p></td><td><p><mark class=\"hl rx\"><b>Verapamil</b></mark> (First-line maintenance; monitor ECG PR interval!) + short <mark class=\"hl rx\"><b>Prednisone taper</b></mark> as transitional bridge!</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u237\">← Case 5</button><button class=\"nv\" data-u=\"u239\">Case 7 →</button></nav></article><article class=\"view unit\" id=\"u239\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 7</span><h1>Idiopathic Intracranial Hypertension (IIH) &amp; Giant Cell Arteritis (GCA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Idiopathic+Intracranial+Hypertension+%28IIH%29+%26+Giant+Cell+Arteritis+%28GCA%29\">🔍 Search on Google</a></header><p><i>(Two \"Do Not Miss\" Secondary Headaches That Cause </i><i><b>Permanent Blindness</b></i><i> if Delayed!)</i></p><h3><b>A. Idiopathic Intracranial Hypertension (IIH / Pseudotumor Cerebri)</b></h3><ul>\n<li class=\"l1\"><b>Classic Patient:</b> <b>Obese female of childbearing age (20–40 yrs)</b> (8:1 F:M).</li>\n<li class=\"l1\"><b>Secondary Mimics to Exclude:</b> <b>Vitamin A / Isotretinoin toxicity</b>, <mark class=\"hl rx\"><b>Tetracyclines (Doxycycline/Minocycline)</b></mark> , Corticosteroid withdrawal, <b>Cerebral Venous Sinus Thrombosis</b>!</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Daily throbbing headache (worse on waking/coughing/straining), <b>transient visual obscurations</b> (brief graying out of vision with posture change), <b>pulsatile tinnitus</b>, <b>CN VI palsy (horizontal diplopia — false localizing sign!)</b>, and <b>Bilateral Papilledema</b>!</li>\n<li class=\"l1\"><b>Diagnosis:</b> <mark class=\"hl mech\"><b>(1) Normal MRI Brain + MRV</b></mark> (MR Venography to rule out tumor and venous sinus thrombosis!) -&gt; <mark class=\"hl mech\"><b>(2) Lumbar Puncture</b></mark> showing <b>Elevated Opening Pressure (&gt; 25 cmH2O)</b> with <mark class=\"hl mech\"><b>NORMAL CSF composition</b></mark> !</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Weight loss (cornerstone — 5–10%!)</b> + <mark class=\"hl rx\"><b>Acetazolamide</b></mark> (reduces CSF production) +/- Topiramate; <b>Optic Nerve Sheath Fenestration</b> or <b>VP Shunt</b> if vision rapidly failing!</li>\n</ul><h3><b>B. Giant Cell (Temporal) Arteritis (GCA — Ophthalmic Emergency!)</b></h3><ul>\n<li class=\"l1\"><b>Classic Patient:</b> Adult <b>&gt; 50 years old</b> (often with <mark class=\"hl lab\"><b>Polymyalgia Rheumatica [PMR]</b></mark> : bilateral shoulder/hip stiffness!).</li>\n<li class=\"l1\"><b>Clinical Picture:</b> <b>New-onset unilateral temporal headache</b>, <b>scalp tenderness</b> (pain combing hair!), <b>JAW CLAUDICATION</b> (pain chewing meat — <b>most specific symptom!</b>), fever/weight loss, <b>sudden painless monocular vision loss</b> (Anterior Ischemic Optic Neuropathy), thickened pulseless temporal artery!</li>\n<li class=\"l1\"><b>Labs &amp; Diagnosis:</b> <mark class=\"hl mech\"><b>Markedly Elevated ESR (&gt; 50–100 mm/hr) &amp; CRP</b></mark> ; Gold Standard = <b>Temporal Artery Biopsy</b> (skip lesions -&gt; take ≥ 2–3 cm segment!).</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>CRITICAL MANAGEMENT RULE:</b></mark> <mark class=\"hl mech\"><b>START HIGH-DOSE CORTICOSTEROIDS IMMEDIATELY UPON CLINICAL SUSPICION — DO NOT WAIT FOR TEMPORAL ARTERY BIOPSY!</b></mark> (Biopsy remains positive for 1–2 weeks after starting steroids! Give <mark class=\"hl rx\"><b>IV Methylprednisolone 1 g/day × 3 days</b></mark> if ANY visual symptoms exist, or Oral Prednisone 40–60 mg/day if no visual symptoms, + <b>Tocilizumab</b> steroid-sparing!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u238\">← Case 6</button><button class=\"nv\" data-u=\"u240\">Case 8 →</button></nav></article><article class=\"view unit\" id=\"u240\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 8</span><h1>Parkinsonʼs Disease &amp; Essential Tremor</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Parkinson%CA%BCs+Disease+%26+Essential+Tremor\">🔍 Search on Google</a></header><h3><b>1. Parkinson’s Disease (PD)</b></h3><ul>\n<li class=\"l1\"><b>Pathophysiology:</b> Progressive loss of dopaminergic neurons in the <b>Substantia Nigra pars compacta</b> with intraneuronal <b>Lewy Bodies</b> (α-synuclein) -&gt; dopamine depletion in nigrostriatal pathway.</li>\n<li class=\"l1\"><b>Classic Clinical Quartet (</b>\"TRAP\"<b>):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>T</b>remor: <b>Asymmetric Resting \"Pill-Rolling\" Tremor (4–6 Hz)</b> — improves with purposeful movement!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>R</b>igidity: <b>\"Cogwheel\" rigidity</b> on passive joint movement.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>A</b>kinesia / <b>B</b>radykinesia (<b>MANDATORY Feature!</b>): Slowness of movement, <b>micrographia</b>, masked expressionless face (<b>hypomimia</b>), <b>shuffling festinating gait </b>with reduced arm swing.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>P</b>ostural Instability (late — falls backward on pull test!).</span></p>\n<ul>\n<li class=\"l1\"><i>Always Rule Out </i><i><b>Drug-Induced Parkinsonism</b></i><i>:</i> <b>Antipsychotics</b> (Haloperidol, Risperidone), <b>Metoclopramide</b>, Prochlorperazine, Valproate!</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><i>Young (&lt; 65 yrs) or Mild:</i> <mark class=\"hl rx\"><b>Dopamine Agonists</b></mark> (<b>Pramipexole, Ropinirole</b> — warn about impulse control disorders: gambling/hypersexuality!) or <b>MAO-B Inhibitors</b> (<b>Rasagiline, Selegiline</b>).</li>\n<li class=\"l2\"><i>Elderly (&gt; 65–70 yrs) or Functionally Impaired (MOST EFFECTIVE DRUG!):</i> <b>Levodopa-Carbidopa</b> (Carbidopa inhibits peripheral DOPA decarboxylase -&gt; prevents nausea/orthostasis; long-term use causes <b>\"wearing-off\" &amp; dyskinesias</b>!).</li>\n<li class=\"l2\"><i>Refractory Motor Fluctuations:</i> <b>Deep Brain Stimulation (DBS)</b> of Subthalamic Nucleus!</li>\n</ul><h3><b>2. Essential Tremor (Comparison!)</b></h3><ul>\n<li class=\"l1\"><b>Features:</b> <b>Bilateral, Symmetric Action / Postural Tremor (6–12 Hz)</b> (worse holding a cup/spoon or writing — <b>ABSENT at rest!</b>), often involves head (\"yes-yes\"/\"no-no\") and voice, strong autosomal dominant family history, classically <b>improves with small amounts of alcohol</b>!</li>\n<li class=\"l1\"><b>Treatment:</b> <mark class=\"hl rx\"><b>Propranolol</b></mark> or <b>Primidone</b> (first-line!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u239\">← Case 7</button><button class=\"nv\" data-u=\"u241\">Case 9 →</button></nav></article><article class=\"view unit\" id=\"u241\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 9</span><h1>Dementia &amp; Major Neurocognitive Disorders (DIFFERENTIATION)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Dementia+%26+Major+Neurocognitive+Disorders+%28DIFFERENTIATION%29\">🔍 Search on Google</a></header><h4><b>High-Yield Differential of Cognitive Decline in the Elderly</b></h4><table class=\"t \"><tr class=\"hd\"><th><p><b>Dementia Type</b></p></th><th><p><b>Pathology</b></p></th><th><p><b>Classic Clinical Clues</b></p></th><th><p><b>Key Management</b></p></th></tr><tr><td><p><b>Alzheimer’s Disease</b> <i>(#1 Overall, ~60–70%)</i></p></td><td><p>β-amyloid plaques + hyperphosphorylated Tau neurofibrillary tangles</p></td><td><p><b>Insidious progressive short-term memory loss</b>, word-finding difficulty, disorientation; preserved motor/gait early!</p></td><td><p><b>Cholinesterase Inhibitors</b> (<b>Donepezil, Rivastigmine, Galantamine</b>) + <b>Memantine </b>(NMDA antagonist for moderate-severe)</p></td></tr><tr><td><p><b>Vascular Dementia</b> <i>(#2 Overall)</i></p></td><td><p>Multiple cortical/subcortical infarcts (HTN, DM, AFib)</p></td><td><p><b>Stepwise cognitive decline</b> + focal neurological signs + MRI white matter/lacunar infarcts</p></td><td><p>Aggressive <b>BP, Diabetes, Lipid, &amp; Antiplatelet control</b>!</p></td></tr><tr><td><p><b>Lewy Body Dementia (DLB)</b></p></td><td><p>Cortical α-synuclein Lewy bodies</p></td><td><p><b>Visual hallucinations (well-formed people/animals)</b> + <b>Fluctuating cognition</b> + <b>Parkinsonism</b> (within 1 yr of dementia) + <b>Severe Antipsychotic Sensitivity</b>!</p></td><td><p>Cholinesterase inhibitors; <b>AVOID typical antipsychotics</b> (use Quetiapine/Pimavanserin if desperate!)</p></td></tr><tr><td><p><b>Frontotemporal Dementia (Pick’s)</b></p></td><td><p>Frontal/temporal lobe atrophy</p></td><td><p>Early <b>behavioral disinhibition, personality change</b>, hyperorality, aphasia (&lt; 65 yrs — memory spared early!)</p></td><td><p>Supportive / SSRIs for behavioral symptoms</p></td></tr><tr><td><p><mark class=\"hl lab\"><b>Normal Pressure Hydrocephalus (NPH) </b></mark><i>(Reversible!)</i></p></td><td><p>Impaired CSF reabsorption -&gt; enlarged ventricles with normal LP pressure</p></td><td><p><b>\"Wet, Wacky, and Wobbly\"</b>: <b>Magnetic Gait Apraxia (FIRST!)</b> + <b>Urinary Incontinence</b> + <b>Dementia</b>!</p></td><td><p><b>Large-Volume LP Tap Test</b> (gait improves!) -&gt; <b>Ventriculoperitoneal (VP) Shunt</b>!</p></td></tr></table><ul>\n<li class=\"l1\"><b>ALWAYS SCREEN FOR REVERSIBLE CAUSES OF DEMENTIA (\"DEMENTIA\"):</b> <mark class=\"hl mech\"><b>TSH</b></mark> (Hypothyroidism), <mark class=\"hl rx\"><b>Vitamin B12</b></mark> , <mark class=\"hl rx\"><b>Calcium</b></mark> , <mark class=\"hl mech\"><b>RFTs/LFTs</b></mark> , <b>Depression (\"Pseudodementia\")</b>, <b>HIV/Syphilis</b> (if risk), and <mark class=\"hl mech\"><b>MRI/CT Brain</b></mark> (rule out <b>Chronic Subdural Hematoma</b>, Tumor, NPH)!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u240\">← Case 8</button><button class=\"nv\" data-u=\"u242\">Case 10 →</button></nav></article><article class=\"view unit\" id=\"u242\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 10</span><h1>Multiple Sclerosis (MS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Multiple+Sclerosis+%28MS%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Pathophysiology</b></h3><p>Chronic immune-mediated <b>demyelinating disease of the Central Nervous System (CNS — brain, spinal cord, optic nerves)</b> sparing peripheral nerves, characterized by lesions <b>\"disseminated in time and space\"</b> (<b>3:1 Female:Male</b>, onset <b>20–40 years</b>).</p><h3><b>2. Clinical Picture (Classic Presentations)</b></h3><ul>\n<li class=\"l1\"><b>Optic Neuritis (#1 Initial Presentation!):</b> Subacute <b>unilateral painful visual loss</b> (pain <b>worsened by eye movement!</b>), reduced color vision (red desaturation), and <b>RAPD</b> (Relative Afferent Pupillary Defect / Marcus Gunn pupil).</li>\n<li class=\"l1\"><b>INO</b> (Internuclear Ophthalmoplegia — <b>MLF</b> [Medial Longitudinal Fasciculus] lesion): Impaired <b>adduction</b> of ipsilateral eye + horizontal nystagmus of abducting contralateral eye on lateral gaze (<i>bilateral INO in a young adult = almost pathognomonic for MS!</i>).</li>\n<li class=\"l1\"><b>Transverse Myelitis:</b> Asymmetric sensory level, spastic paraparesis, bladder dysfunction, <b>Lhermitte’s Sign</b> (electric-shock sensation down spine on neck flexion!).</li>\n<li class=\"l1\"><b>Uhthoff’s Phenomenon:</b> Transient worsening of symptoms with <b>heat</b> (hot showers, fever, exercise!).</li>\n</ul><h3><b>3. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Diagnostic Gold Standard:</b> <mark class=\"hl mech\"><b>MRI Brain &amp; Spinal Cord with Gadolinium</b></mark> (<b>McDonald Criteria</b>): Periventricular ovoid white matter plaques perpendicular to ventricles (<b>\"Dawson’s Fingers\"</b>); <b>enhancing lesions = active</b>, non-enhancing = old!</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>CSF Analysis (If MRI equivocal):</b></mark> <b>Oligoclonal IgG Bands</b> (present in CSF, absent in serum!).</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><i>Acute Relapse (Disabling flare):</i> <mark class=\"hl rx\"><b>High-Dose IV Methylprednisolone (1,000 mg/day × 3–5 days)</b></mark> -&gt; Plasmapheresis if steroid-refractory!</li>\n<li class=\"l2\"><i>Disease-Modifying Therapies (DMTs — Reduce Relapses &amp; Disability!):</i> High-efficacy (<b>Ocrelizumab, Natalizumab</b> [monitor JC virus for <b>PML</b>!], <b>Ofatumumab, Fingolimod</b>) or Moderate-efficacy (<b>Dimethyl fumarate, Interferon-beta, Glatiramer acetate</b>).</li>\n<li class=\"l2\"><i>Symptomatic:</i> <b>Baclofen/Tizanidine</b> (spasticity), Oxybutynin (bladder), Amantadine/Modafinil (fatigue).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u241\">← Case 9</button><button class=\"nv\" data-u=\"u243\">Case 11 →</button></nav></article><article class=\"view unit\" id=\"u243\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 11</span><h1>Guillain-Barré Syndrome (GBS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Guillain-Barr%C3%A9+Syndrome+%28GBS%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Etiology</b></h3><p>Acute immune-mediated <b>demyelinating (AIDP) or axonal polyradiculoneuropathy</b> of the <b>Peripheral Nervous System</b>, triggered <b>1–3 weeks after an infection</b> via molecular mimicry!</p>\n<ul>\n<li class=\"l1\"><b>#1 Preceding Trigger:</b> <i><b>Campylobacter jejuni</b></i> gastroenteritis! (Also CMV, EBV, <i>Mycoplasma</i>, Influenza, Zika, COVID-19).</li>\n</ul><h3><b>2. Clinical Picture (ASCENDING SYMMETRIC WEAKNESS + AREFLEXIA!)</b></h3><ul>\n<li class=\"l1\"><b>Rapidly progressive, symmetric ascending flaccid paralysis</b> starting in the legs (\"difficulty climbing stairs / standing from chair\") spreading upward to arms, facial muscles (bilateral CN VII palsy), bulbar muscles, and <b>diaphragm</b>!</li>\n<li class=\"l1\"><b>Absent or Markedly Diminished Deep Tendon Reflexes (Areflexia)</b> early!</li>\n<li class=\"l1\">Mild distal paresthesias (\"glove-and-stocking\"), back pain, and <mark class=\"hl lab\"><b>LIFE-THREATENING AUTONOMIC INSTABILITY</b></mark> (labile BP, severe arrhythmias)!</li>\n<li class=\"l1\"><i>Variant — Miller Fisher Syndrome:</i> Triad of <b>Ophthalmoplegia + Ataxia + Areflexia</b> (Anti-GQ1b antibodies!).</li>\n</ul><h3><b>3. Investigations &amp; Emergency Monitoring</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Lumbar Puncture (CSF):</b></mark> Classic <b>\"Albuminocytologic Dissociation\"</b> — <mark class=\"hl mech\"><b>Markedly Elevated CSF Protein (&gt; 45–100 mg/dL)</b></mark> with <mark class=\"hl mech\"><b>NORMAL WBC count (&lt; 5–10 cells)</b></mark> ! <i>(Note: CSF protein may still be normal in Week 1!)</i></li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Nerve Conduction Studies / EMG:</b></mark> Confirms demyelinating neuropathy (slow conduction, prolonged F-waves).</li>\n<li class=\"l1\"><b>CRITICAL HOSPITAL MONITORING:</b> <mark class=\"hl lab\"><b>Admit ALL GBS patients to monitor Bedside Forced Vital Capacity (FVC) every 4–6 hours!</b></mark> <b>Electively Intubate</b> if <mark class=\"hl mech\"><b>FVC &lt; 15– 20 mL/kg</b></mark> or Negative Inspiratory Force worse than <b>−30 cmH2O</b> (\"20/30/40 rule\") or bulbar dysphagia! <i>(NEVER rely on SpO2 — hypoxia occurs AFTER respiratory arrest!)</i></li>\n</ul><h3><b>4. Treatment (START EARLY — Do NOT Give Corticosteroids!)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl rx\"><b>IVIG (Intravenous Immunoglobulin — 0.4 g/kg/day × 5 days)</b></mark> <b>OR</b> <mark class=\"hl rx\"><b>Plasmapheresis (Plasma Exchange — 5 sessions)</b></mark> — equally effective!</li>\n<li class=\"l1\"><b>CRITICAL RULE:</b> <mark class=\"hl lab\"><b>Corticosteroids (Oral/IV) are INEFFECTIVE in GBS</b></mark> and must NOT be given! Add <mark class=\"hl lab\"><b>DVT prophylaxis</b></mark> (LMWH) and telemetry!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u242\">← Case 10</button><button class=\"nv\" data-u=\"u244\">Case 12 →</button></nav></article><article class=\"view unit\" id=\"u244\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 12</span><h1>Myasthenia Gravis (MG) &amp; Myasthenic Crisis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Myasthenia+Gravis+%28MG%29+%26+Myasthenic+Crisis\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Pathophysiology</b></h3><p>Autoimmune <b>Post-Synaptic Neuromuscular Junction</b> disorder caused by <b>IgG autoantibodies blocking/destroying Nicotinic Acetylcholine Receptors (AChRs)</b> (or <b>MuSK</b> receptors), reducing functional receptors. Strongly associated with <b>Thymic Hyperplasia (~65%) or Thymoma (~15%)</b>!</p><h3><b>2. Clinical Picture (FLUCTUATING FATIGABLE WEAKNESS — WORSE AT END OF DAY!)</b></h3><ul>\n<li class=\"l1\"><b>Ocular (#1 Initial Symptom):</b> Asymmetric <b>ptosis</b> (worsens looking upward!) and <b>diplopia</b>!</li>\n<li class=\"l1\"><b>Bulbar &amp; Generalized:</b> Dysphagia, nasal regurgitation, slurred nasal voice (worsens counting aloud!), proximal limb weakness (combing hair/climbing stairs).</li>\n<li class=\"l1\"><b>NORMAL Deep Tendon Reflexes, NORMAL Pupils, and NO Sensory Loss!</b></li>\n<li class=\"l1\"><i>Drugs That Trigger Fatal Myasthenic Crisis (AVOID!):</i> <mark class=\"hl rx\"><b>Aminoglycosides, Fluoroquinolones, Macrolides, Beta-blockers, Magnesium Sulfate, Neuromuscular blockers, Procainamide</b></mark> !</li>\n</ul><h3><b>3. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Labs:</b> <b>Anti-AChR Antibodies</b> (~85% generalized MG, ~50% ocular -&gt; Gold Standard initial test!), <b>Anti-MuSK Antibodies</b> (if AChR-negative), <b>CT Chest</b> (mandatory to rule out <b>Thymoma</b>!), <mark class=\"hl mech\"><b>TSH</b></mark> (autoimmune overlap).</li>\n<li class=\"l1\"><b>Electrodiagnostics:</b> <b>Repetitive Nerve Stimulation</b> shows <b>Decremental Response</b> (&gt; 10% amplitude drop); <mark class=\"hl mech\"><b>Single-Fiber EMG</b></mark> (most sensitive). <i>(Bedside </i><i><b>Ice Pack Test</b></i><i>: holding ice over ptotic eyelid for 2 min improves ptosis!)</i></li>\n<li class=\"l1\"><b>Chronic Treatment:</b></li>\n<li class=\"l2\"><i>Symptomatic:</i> <b>Pyridostigmine</b> (acetylcholinesterase inhibitor).</li>\n<li class=\"l2\"><i>Immunosuppression:</i> <mark class=\"hl rx\"><b>Oral Prednisone</b></mark> + <mark class=\"hl rx\"><b>Azathioprine</b></mark> or <mark class=\"hl rx\"><b>Mycophenolate Mofetil</b></mark> (+ <b>Thymectomy</b> in ALL Thymoma patients AND AChR+ generalized MG &lt; 50–65 yrs!).</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>MYASTHENIC CRISIS (Respiratory Muscle Failure -&gt; Bulbar weakness + FVC &lt; 15–20 mL/kg):</b></mark></li>\n<li class=\"l2\"><b>Intubate early</b> + <b>STOP Pyridostigmine temporarily</b> (avoids excess airway secretions) + <mark class=\"hl rx\"><b>Plasmapheresis or IVIG</b></mark> + High-dose steroids! <i>(Note: Cholinergic Crisis from Pyridostigmine overdose causes </i><i><b>SLUDGE</b></i><i> muscarinic toxicity [salivation, lacrimation, miosis, bradycardia, diarrhea] + fasciculations!)</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u243\">← Case 11</button><button class=\"nv\" data-u=\"u245\">Case 13 →</button></nav></article><article class=\"view unit\" id=\"u245\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 13</span><h1>Peripheral Neuropathy &amp; Carpal Tunnel Syndrome</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Peripheral+Neuropathy+%26+Carpal+Tunnel+Syndrome\">🔍 Search on Google</a></header><h3><b>A. Distal Symmetric Polyneuropathy (Diabetic &amp; Other Causes)</b></h3><ul>\n<li class=\"l1\"><b>Etiology (Separated — Mnemonic: \"DANG THERAPIST\"):</b> <b>D</b>iabetes Mellitus (#1!), <b>A</b>lcohol, <b>N</b>utritional (<b>Vitamin B12</b>, B1, B6 deficiency/excess), <b>G</b>BS / <b>G</b>enetic (Charcot-Marie-Tooth), <b>T</b>oxins (Lead, Arsenic), <b>H</b>ypothyroidism, <b>E</b>nd-stage renal/uremia, <b>R</b>heumatologic (<mark class=\"hl lab\"><b> SLE/PAN/Vasculitis</b></mark> -&gt; mononeuritis multiplex!), <b>A</b>myloidosis, <b>P</b>orphyria, <b>I</b>nfections (Leprosy, HIV, HCV), <b>S</b>tatin/Chemo/Drugs (<mark class=\"hl rx\"><b> Isoniazid</b></mark> , Vincristine, Cisplatin, Amiodarone), <b>T</b>umor (Paraneoplastic/Myeloma).</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Symmetric <b>\"Stocking-Glove\"</b> numbness, burning/tingling pain (worse at night!), loss of ankle jerks and <b>vibration/10-g monofilament sensation</b>.</li>\n<li class=\"l1\"><b>Minimum Workup:</b> <mark class=\"hl rx\"><b>HbA1c/Fasting Glucose, Vitamin B12 (+ MMA), TSH, SPEP</b></mark> (Serum Protein Electrophoresis), <mark class=\"hl mech\"><b>RFTs/LFTs</b></mark> .</li>\n<li class=\"l1\"><b>Pain Treatment:</b> <b>Duloxetine (SNRI)</b>, <b>Pregabalin / Gabapentin</b>, or <b>Amitriptyline</b> (avoid opioids!).</li>\n</ul><h3><b>B. Carpal Tunnel Syndrome (#1 Entrapment Neuropathy!)</b></h3><ul>\n<li class=\"l1\"><b>Pathology:</b> Compression of the <b>Median Nerve</b> beneath the transverse carpal ligament at the wrist (<b>Risk factors:</b> Repetitive wrist flexion, <mark class=\"hl lab\"><b>Pregnancy</b></mark> , <mark class=\"hl lab\"><b>Hypothyroidism</b></mark> , <mark class=\"hl lab\"><b>Rheumatoid Arthritis</b></mark> , <b>DM</b>, Acromegaly, Obesity).</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Numbness, tingling, and pain in the <b>palmar aspect of Thumb, Index, Middle, and Radial half of Ring Finger</b>, classically <b>waking the patient at night (relieved by shaking hands — \"Flick Sign\")</b>; late <b>thenar eminence atrophy</b>!</li>\n<li class=\"l1\"><b>Exam &amp; Diagnosis:</b> <b>Phalen’s Maneuver</b> (wrist flexion × 60 sec reproduces symptoms) &amp; <b>Tinel’s Sign</b> (tapping wrist); confirm with <mark class=\"hl mech\"><b>Nerve Conduction Studies (NCS/EMG)</b></mark> .</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Neutral Wrist Splint at night</b> (first-line) -&gt; Local corticosteroid injection -&gt; <b>Surgical Carpal Tunnel Release</b> if refractory or thenar atrophy!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u244\">← Case 12</button><button class=\"nv\" data-u=\"u246\">Case 14 →</button></nav></article><article class=\"view unit\" id=\"u246\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 14</span><h1>Lumbar Disc Herniation (SCIATICA) &amp; Cauda Equina Syndrome</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Lumbar+Disc+Herniation+%28SCIATICA%29+%26+Cauda+Equina+Syndrome\">🔍 Search on Google</a></header><h3><b>1. Lumbar Disc Herniation (Radiculopathy)</b></h3><ul>\n<li class=\"l1\"><b>Most Common Levels:</b> <b>L4–L5</b> (compresses <b>L5 root</b>) and <b>L5–S1</b> (compresses <b>S1 root</b>).</li>\n<li class=\"l2\"><i>L5 Radiculopathy:</i> Pain radiating down lateral leg to dorsum of foot/big toe + <b>weakness of Great Toe &amp; Ankle Dorsiflexion (Foot Drop!)</b>; normal reflexes.</li>\n<li class=\"l2\"><i>S1 Radiculopathy:</i> Pain radiating down posterior calf to lateral foot/sole + <b>weakness of Plantarflexion</b> (cannot walk on tiptoes!) + <b>Absent Ankle (Achilles) Reflex</b>!</li>\n<li class=\"l1\"><b>Exam:</b> Positive <b>Straight Leg Raise (SLR)</b> test (reproduces shooting radicular pain below knee at 30–70° elevation!).</li>\n<li class=\"l1\"><b>Management:</b> <b>&gt; 85–90% recover within 4–6 weeks conservatively!</b> -&gt; Stay active (NO strict bed rest!), <mark class=\"hl rx\"><b>NSAIDs</b></mark> + physical therapy! <mark class=\"hl mech\"><b>NO MRI needed in first 4–6 weeks UNLESS Red Flags exist!</b></mark></li>\n</ul><h3><b>2. CAUDA EQUINA SYNDROME (NEUROSURGICAL EMERGENCY!)</b></h3><ul>\n<li class=\"l1\"><b>Cause:</b> Massive central lumbar disc herniation, epidural abscess/hematoma, or tumor compressing lumbosacral nerve roots (L2–S5) below the conus medullaris!</li>\n</ul><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ Classic Red Flags (ASK IN EVERY BACK PAIN PATIENT!):</b></mark></p></div></div><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Urinary Retention with Overflow Incontinence</b> (or fecal incontinence / decreased anal sphincter tone).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Saddle Anesthesia</b> (numbness over buttocks, perineum, inner thighs).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Bilateral Sciatica</b> and progressive lower extremity weakness!</span></p>\n<ul>\n<li class=\"l1\"><b>Action:</b> <mark class=\"hl mech\"><b>STAT MRI Lumbosacral Spine</b></mark> -&gt; <mark class=\"hl lab\"><b>EMERGENT SURGICAL LAMINECTOMY &amp; DECOMPRESSION (&lt; 24–48 hrs)</b></mark> to prevent permanent paralysis and incontinence!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u245\">← Case 13</button><button class=\"nv\" data-u=\"u247\">Case 15 →</button></nav></article><article class=\"view unit\" id=\"u247\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 15</span><h1>Trigeminal Neuralgia &amp; Amyotrophic Lateral Sclerosis (ALS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Trigeminal+Neuralgia+%26+Amyotrophic+Lateral+Sclerosis+%28ALS%29\">🔍 Search on Google</a></header><h3><b>A. Trigeminal Neuralgia (</b><b>Tic Douloureux</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Etiology:</b> Vascular compression (usually Superior Cerebellar Artery) of <b>CN V</b> root entry zone (<b>NOTE:</b> If <b>young patient &lt; 40 yrs</b> or <b>bilateral</b> -&gt; rule out <b>Multiple Sclerosis</b>!).</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Recurrent, brief (<b>seconds to &lt; 2 min</b>), excruciating <b>\"electric-shock\" stabbing unilateral facial pain</b> along <b>V2 (maxillary) or V3 (mandibular) </b>branches, triggered by <b>light touch, chewing, talking, brushing teeth, or cold breeze</b>! Normal facial sensation/corneal reflex on exam!</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Carbamazepine</b> (or <b>Oxcarbazepine</b>) = <b>First-Line Drug of Choice!</b> (Check Na+ &amp; LFTs/CBC). Microvascular decompression surgery if drug-refractory.</li>\n</ul><h3><b>B. Amyotrophic Lateral Sclerosis (ALS / Lou Gehrig’s Disease)</b></h3><ul>\n<li class=\"l1\"><b>Pathology:</b> Progressive degeneration of BOTH <b>Upper Motor Neurons (UMN)</b> (corticospinal tracts) AND <b>Lower Motor Neurons (LMN)</b> (anterior horn cells/bulbar nuclei).</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Asymmetric progressive limb weakness/clumsiness or <b>bulbar dysphagia/dysarthria</b> showing <b>SIMULTANEOUS UMN + LMN signs in the same limb/region</b>:</li>\n<li class=\"l2\"><i>UMN:</i> Spasticity, <b>hyperreflexia</b>, clonus, positive Babinski sign!</li>\n<li class=\"l2\"><i>LMN:</i> Muscle <b>atrophy</b>, <b>fasciculations</b> (classic: <b>tongue fasciculations!</b>), weakness!</li>\n<li class=\"l2\"><b>CRITICAL NEGATIVES:</b> <b>COMPLETELY SPARES Sensation, Extraocular Eye Movements, Cognition (usually), and Bowel/Bladder Sphincters!</b></li>\n<li class=\"l1\"><b>Diagnosis &amp; Treatment:</b> Clinical + <mark class=\"hl mech\"><b>EMG</b></mark> (widespread denervation) + <mark class=\"hl mech\"><b>MRI Brain/Spine</b></mark> (to exclude cervical myelopathy/compression!).</li>\n<li class=\"l2\"><b>Treatment:</b> <b>Riluzole</b> (glutamate inhibitor — modestly prolongs survival by 2–3 mos) + <b>Edaravone</b> + <b>NIV (BiPAP)</b> when FVC drops + PEG tube for dysphagia (death usually from respiratory failure within 3–5 years).</li>\n</ul>\n<p class=\"muted\"><i>End of Part 10A — Clinical Neurology (15 Cases Complete!</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u246\">← Case 14</button><button class=\"nv\" data-u=\"u248\">Case 16 →</button></nav></article><article class=\"view unit\" id=\"u248\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 16</span><h1>Major Depressive Disorder (MDD) &amp; Suicide Risk Assessment</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Major+Depressive+Disorder+%28MDD%29+%26+Suicide+Risk+Assessment\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><b>MDD</b> (Major Depressive Disorder) is a mood disorder diagnosed when <b>≥ 5 of 9 symptoms</b> persist nearly every day for <b>≥ 2 consecutive weeks</b>, representing a change from baseline and including <b>at least 1 core symptom</b>: <b>(1) Depressed mood</b> or <b>(2) Anhedonia</b> (loss of interest/pleasure), causing significant distress/impairment without prior mania/hypomania.</p><h3><b>2. Etiology &amp; Risk Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Neurobiological / Genetic:</b> Dysregulation of monoamine neurotransmitters (<mark class=\"hl rx\"><b> Serotonin [5-HT], Norepinephrine [NE], Dopamine [DA]</b></mark> ), <b>HPA</b> (Hypothalamic-Pituitary-Adrenal) axis hyperactivity (elevated cortisol), high heritability (~35–40%).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Medical / Substance Mimics (ALWAYS RULE OUT FIRST!):</b> <mark class=\"hl lab\"><b>Hypothyroidism</b></mark> (#1 endocrine mimic!), Anemia, Vitamin B12/D deficiency, Parkinson’s/Stroke/Dementia, Medications (<mark class=\"hl rx\"><b> Beta-blockers [older lipophilic], Corticosteroids, Isotretinoin, Interferon</b></mark> ), Alcohol/substance withdrawal.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Psychosocial:</b> Bereavement, chronic medical illness, trauma, unemployment, isolation.</span></p><h3><b>3. Clinical Picture (Mnemonic: \"SIG E CAPS\" — ≥ 5 for ≥ 2 Weeks!)</b></h3><ul>\n<li class=\"l1\"><b>Depressed mood</b> AND/OR <b>Anhedonia</b> <b>PLUS:</b></li>\n<li class=\"l2\"><b>S</b>leep disturbance (<b>insomnia [early-morning awakening]</b> or hypersomnia).</li>\n<li class=\"l2\"><b>I</b>nterest loss (<b>Anhedonia</b>).</li>\n<li class=\"l2\"><b>G</b>uilt / feelings of worthlessness.</li>\n<li class=\"l2\"><b>E</b>nergy loss / fatigue.</li>\n<li class=\"l2\"><b>C</b>oncentration difficulty / indecisiveness.</li>\n<li class=\"l2\"><b>A</b>ppetite / weight change (decrease or increase &gt; 5%).</li>\n<li class=\"l2\"><b>P</b>sychomotor agitation or retardation.</li>\n<li class=\"l2\"><b>S</b>uicidal ideation (recurrent thoughts of death, plan, or attempt).</li>\n</ul><h3><b>4. Suicide Risk Assessment (SAD PERSONS — High-Risk Red Flags!)</b></h3><ul>\n<li class=\"l1\"><b>High-Risk Factors:</b> Male sex (higher completion; females higher attempts), Elderly &gt; 65 or Adolescent, Depression/Psychosis, <b>Prior suicide attempt (#1 single strongest predictor!)</b>, Substance abuse, <b>Organized lethal plan + access to means</b>, No social support, Chronic painful illness.</li>\n<li class=\"l1\"><b>Immediate Action:</b> <b>ASK DIRECTLY about suicidal thoughts/plans</b> (asking does NOT plant the idea!). If active plan/intent -&gt; <b>Immediate Psychiatric Hospitalization (Involuntary if needed for safety!)</b>, 1:1 observation, remove sharp objects/belts!</li>\n</ul><h3><b>5. Investigations &amp; DDx</b></h3><ul>\n<li class=\"l1\"><b>Mandatory Organic Rule-Out Labs:</b> <mark class=\"hl mech\"><b>TSH</b></mark> (Thyroid-Stimulating Hormone), <mark class=\"hl mech\"><b>CBC</b></mark> (Complete Blood Count), <b>CMP</b> (Comprehensive Metabolic Panel), <mark class=\"hl rx\"><b>Vitamin B12</b></mark> , Urine Drug Screen.</li>\n<li class=\"l1\"><b>DDx:</b> <b>Bipolar Depression</b> (<b>CRITICAL: ALWAYS screen for past mania/hypomania BEFORE starting an antidepressant — antidepressants alone can trigger acute mania!</b>), Persistent Depressive Disorder (Dysthymia ≥ 2 yrs), Grief/Adjustment disorder, Hypothyroidism, Dementia (\"Pseudodementia\").</li>\n</ul><h3><b>6. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Mild-to-Moderate MDD:</b> <b>CBT</b> (Cognitive Behavioral Therapy) and/or <b>First-Line Antidepressant</b>:</li>\n<li class=\"l2\"><b>SSRIs</b> (Selective Serotonin Reuptake Inhibitors — <b>Sertraline, Escitalopram, Fluoxetine, Citalopram</b>): Safest, best tolerated. <i>Warn patient: takes </i><i><b>4–6 weeks</b></i><i> for full mood response; GI upset/sexual dysfunction common!</i></li>\n<li class=\"l2\"><b>SNRIs</b> (Serotonin-Norepinephrine Reuptake Inhibitors — <b>Venlafaxine, Duloxetine</b>): Great if comorbid <b>chronic/neuropathic pain</b>!</li>\n<li class=\"l2\"><b>Atypical Antidepressants:</b> <b>Bupropion</b> (no sexual side effects, aids smoking cessation; <i>AVOID in Seizures or Eating Disorders!</i>); <b>Mirtazapine</b> (sedating + stimulates appetite — great for elderly with insomnia &amp; weight loss!).</li>\n<li class=\"l1\"><b>FDA Black-Box Warning:</b> Monitor children, adolescents, and young adults (&lt; 25 yrs) closely during the <b>first 2–4 weeks</b> of starting SSRIs for transient worsening of suicidal ideation!</li>\n<li class=\"l1\"><b>Treatment-Resistant / Severe Psychotic / Life-Threatening Suicidal / Catatonic MDD:</b> <b>ECT</b> (Electroconvulsive Therapy — fastest, most effective treatment, safe in <mark class=\"hl lab\"><b>Pregnancy</b></mark> !).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u247\">← Case 15</button><button class=\"nv\" data-u=\"u249\">Case 17 →</button></nav></article><article class=\"view unit\" id=\"u249\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 17</span><h1>Bipolar I &amp; II Disorder (ACUTE MANIA &amp; MAINTENANCE)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Bipolar+I+%26+II+Disorder+%28ACUTE+MANIA+%26+MAINTENANCE%29\">🔍 Search on Google</a></header><h3><b>1. Definitions (Mania vs. Hypomania)</b></h3><ul>\n<li class=\"l1\"><b>Bipolar I Disorder:</b> Requires <b>≥ 1 Manic Episode</b> (depression is common but NOT required for diagnosis!).</li>\n<li class=\"l2\"><i>Mania:</i> Abnormally elevated/expansive/irritable mood + increased energy lasting <b>≥ 7 days</b> (or <b>ANY duration if hospitalization or psychosis is present!</b>) causing <b>severe functional impairment</b>.</li>\n<li class=\"l1\"><b>Bipolar II Disorder:</b> Requires <b>≥ 1 Major Depressive Episode PLUS ≥ 1 Hypomanic Episode</b> (<b>NEVER a full manic episode!</b>).</li>\n<li class=\"l2\"><i>Hypomania:</i> Same elevated symptoms lasting <b>≥ 4 consecutive days</b>, <b>NO psychosis, NO hospitalization, NO severe functional impairment</b>.</li>\n</ul><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Genetic (~70–85% heritability — highest among psychiatric disorders!).</b></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Neurochemical:</b> Dopamine/Glutamate hyperactivity and circadian rhythm dysregulation.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Medical / Substance Triggers:</b> Corticosteroids, <b>Antidepressant monotherapy</b>, Stimulants (cocaine/amphetamines), Hyperthyroidism, Frontal lobe lesions.</span></p><h3><b>3. Clinical Picture (Mnemonic for Mania: \"DIGFAST\" — ≥ 3 [4 if irritable]!)</b></h3><ul>\n<li class=\"l1\"><b>D</b>istractibility | <b>I</b>ndiscretion (reckless spending, hypersexuality, dangerous driving) | <b>G</b>randiosity (inflated self-esteem/delusions) | <b>F</b>light of ideas (racing thoughts) | <b>A</b>ctivity increase (goal-directed agitation) | <b>S</b>leep deficit (<b>decreased NEED for sleep</b> — feels rested after 2 hrs!) | <b>T</b>alkativeness (pressured rapid speech).</li>\n</ul><h3><b>4. Investigations &amp; DDx</b></h3><ul>\n<li class=\"l1\"><b>Labs:</b> <mark class=\"hl mech\"><b>TSH</b></mark> , <b>Urine Drug Screen</b> (cocaine/amphetamines!), <mark class=\"hl mech\"><b>CBC, CMP, Pregnancy Test</b></mark> (before Lithium/Valproate!).</li>\n<li class=\"l1\"><b>DDx:</b> Substance intoxication, Hyperthyroidism, <b>Schizoaffective Disorder</b>, <b>ADHD</b> (chronic childhood onset, not episodic), Borderline Personality Disorder (chronic affective instability, not sustained days-long episodes).</li>\n</ul><h3><b>5. Treatment</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Acute Mania (Medical/Psychiatric Emergency!):</b></span></p>\n<ul>\n<li class=\"l2\"><b>STOP all Antidepressants immediately!</b></li>\n<li class=\"l2\"><b>Second-Generation Antipsychotic (SGA — Fastest acting!):</b> <b>Risperidone, Olanzapine, Quetiapine, Aripiprazole, or Haloperidol</b> <b>PLUS/OR</b> a <b>Mood Stabilizer </b>(<b>Lithium</b> or <b>Valproate</b>); add short-term <b>Benzodiazepine (Lorazepam)</b> for acute agitation/sleep!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Maintenance Mood Stabilization:</b></span></p>\n<ul>\n<li class=\"l2\"><b>Lithium:</b> <b>Gold Standard</b> (ONLY mood stabilizer proven to <b>reduce Suicide Risk!</b>). <i>Check </i><mark class=\"hl mech\"><i><b>RFTs, TSH, Ca++, ECG, &amp; Pregnancy test</b></i></mark><i> before starting; therapeutic window </i><i><b>0.6–1.2 mEq/L</b></i><i>!</i></li>\n<li class=\"l2\"><b>Valproate:</b> Rapidly effective for mixed/rapid-cycling mania (<i>TERATOGENIC — avoid in women of childbearing potential!</i>).</li>\n<li class=\"l2\"><b>Lamotrigine:</b> <b>Best for preventing Bipolar DEPRESSION</b> (<i>SLOW titration required to prevent </i><mark class=\"hl lab\"><i><b>SJS/TEN</b></i></mark><i> !</i> — ineffective for acute mania!).</li>\n<li class=\"l2\"><b>Quetiapine / Lurasidone:</b> Effective for <b>Bipolar Depression</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u248\">← Case 16</button><button class=\"nv\" data-u=\"u250\">Case 18 →</button></nav></article><article class=\"view unit\" id=\"u250\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 18</span><h1>Generalized Anxiety Disorder (GAD) &amp; Panic Disorder</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Generalized+Anxiety+Disorder+%28GAD%29+%26+Panic+Disorder\">🔍 Search on Google</a></header><h3><b>1. Definitions &amp; Comparison</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>GAD (Generalized Anxiety Disorder)</b></p></th><th><p><b>Panic Disorder</b></p></th></tr><tr><td><p><b>Core Diagnostic Criterion</b></p></td><td><p>Excessive, uncontrollable worry about <b>multiple everyday topics</b> for <b>≥ 6 MONTHS</b> + ≥ 3 somatic symptoms (restlessness, fatigue, poor concentration, irritability, muscle tension, sleep trouble)</p></td><td><p><b>Recurrent, UNEXPECTED Panic Attacks</b> (abrupt surge of intense fear peaking within <b>10 minutes</b> + ≥ 4 symptoms: palpitations, sweating, trembling, dyspnea, chest pain, dizziness, fear of dying/going crazy) <b>PLUS ≥ 1 MONTH</b> of worry about future attacks or agoraphobia avoidance!</p></td></tr><tr><td><p><b>Organic Mimics to Rule Out</b></p></td><td><p><mark class=\"hl lab\"><b>Hyperthyroidism</b></mark> , Caffeine/Stimulant excess, Asthma, Arrhythmias</p></td><td><p><mark class=\"hl lab\"><b>ACS / Arrhythmia (SVT/AFib)</b></mark> , <mark class=\"hl lab\"><b>Pulmonary Embolism</b></mark> , <mark class=\"hl lab\"><b>Asthma</b></mark> , <b>Pheochromocytoma</b>, <b>Hypoglycemia</b>, Hyperthyroidism!</p></td></tr></table><h3><b>2. Treatment</b></h3><ul>\n<li class=\"l1\"><b>First-Line Long-Term (BOTH GAD &amp; Panic Disorder):</b></li>\n<li class=\"l2\"><b>CBT</b> (Cognitive Behavioral Therapy) <b>AND/OR SSRI</b> (<b>Sertraline, Escitalopram, Paroxetine</b>) or <b>SNRI</b> (<b>Venlafaxine</b>). <i>(Note: Start SSRIs at </i><i><b>HALF normal dose</b></i><i> in Panic Disorder for 1 week because high initial doses cause transient jitteriness!)</i></li>\n<li class=\"l1\"><b>GAD Adjuncts:</b> <b>Buspirone</b> (takes 2–4 wks; non-sedating, non-addictive!).</li>\n<li class=\"l1\"><b>Acute Severe Panic Attack Rescue:</b> <b>Short-term Benzodiazepine</b> (Alprazolam/Lorazepam) ONLY as a brief 2–4 week bridge while waiting for SSRI to work (<i>NEVER prescribe chronic benzodiazepines due to dependence/tolerance!</i>).</li>\n<li class=\"l1\"><i>Compare </i><i><b>Social Anxiety Disorder</b></i><i>:</i> Fear of embarrassment/scrutiny in social/performance situations -&gt; <b>CBT + SSRI</b> (for generalized) or <mark class=\"hl rx\"><b>Propranolol</b></mark> 1 hr before isolated public speaking (performance-only)!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u249\">← Case 17</button><button class=\"nv\" data-u=\"u251\">Case 19 →</button></nav></article><article class=\"view unit\" id=\"u251\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 19</span><h1>Obsessive-Compulsive Disorder (OCD) &amp; PTSD</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Obsessive-Compulsive+Disorder+%28OCD%29+%26+PTSD\">🔍 Search on Google</a></header><h3><b>A. Obsessive-Compulsive Disorder (OCD)</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Presence of <b>Obsessions</b> (recurrent, intrusive, unwanted thoughts/urges causing <b>marked anxiety</b>, e.g., contamination, symmetry, harm — <i>ego-dystonic: patient knows they are irrational!</i>) and/or <b>Compulsions</b> (repetitive physical/mental acts performed to neutralize anxiety, e.g., handwashing, checking locks, counting) consuming <b>&gt; 1 hour/day</b>.</li>\n<li class=\"l1\"><i>Distinguish From </i><i><b>OCPD</b></i><i> (Obsessive-Compulsive Personality Disorder):</i> OCPD is <b>ego-syntonic</b> (rigid perfectionism/orderliness without true obsessions/compulsions!).</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>CBT with ERP</b> (<b>Exposure and Response Prevention</b> — Gold Standard psychotherapy!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>High-Dose SSRI</b> (<b>Fluoxetine, Sertraline, Fluvoxamine, Paroxetine</b> — requires <b>higher doses and longer 8–12 week trial</b> than depression!) OR <b>Clomipramine </b>(TCA — most potent drug, more anticholinergic/cardiac side effects!).</span></p><h3><b>B. Post-Traumatic Stress Disorder (PTSD)</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Trauma-related disorder following exposure to actual/threatened death, serious injury, or sexual violence, lasting <b>&gt; 1 MONTH</b>! <i>(If symptoms last </i><i><b>3 days to 1 month</b></i><i> -&gt; </i><i><b>Acute Stress Disorder</b></i><i>!)</i></li>\n<li class=\"l1\"><b>4 Symptom Clusters:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Intrusion:</b> Nightmares, distressing <b>flashbacks</b>, intrusive memories.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Avoidance:</b> Avoiding trauma reminders/places/thoughts.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Negative Mood/Cognition:</b> Detachment, guilt, amnesia for trauma details.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Hyperarousal:</b> Hypervigilance, exaggerated startle, irritability, insomnia.</span></p>\n<ul>\n<li class=\"l1\"><b>Treatment:</b> <b>Trauma-Focused CBT / EMDR</b> (Eye Movement Desensitization and Reprocessing) + <b>SSRI</b> (<b>Sertraline / Paroxetine</b>) or <b>Venlafaxine</b> + <b>Prazosin</b> (α1-blocker — specifically treats <b>PTSD trauma nightmares</b>!). <i>(AVOID Benzodiazepines in PTSD — worsen outcomes and high addiction risk!)</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u250\">← Case 18</button><button class=\"nv\" data-u=\"u252\">Case 20 →</button></nav></article><article class=\"view unit\" id=\"u252\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 20</span><h1>Schizophrenia &amp; Acute Psychosis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Schizophrenia+%26+Acute+Psychosis\">🔍 Search on Google</a></header><h3><b>1. Definition (DSM-5 Duration Rule — Memorize!)</b></h3><p>Chronic psychotic disorder lasting <b>≥ 6 MONTHS total</b> (including ≥ 1 month of active-phase symptoms) with functional decline and <b>≥ 2 of the following</b> (at least 1 must be #1, #2, or #3):</p>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Delusions</b> (fixed false beliefs — persecutory, grandiose, somatic).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Hallucinations</b> (sensory perceptions without stimuli — <b>Auditory hallucinations</b> commenting on behavior are #1!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Disorganized Speech</b> (loose associations, word salad, tangentiality).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Grossly Disorganized or Catatonic Behavior</b>.</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Negative Symptoms</b> (<b>\"5 As\"</b>: <b>A</b>ffective flattening, <b>A</b>logia [poverty of speech], <b>A</b>volition [lack of motivation], <b>A</b>nhedonia, <b>A</b>sociality).</span></p>\n<p><i>(Duration Timeline: </i><i><b>&lt; 1 Month</b></i><i> = Brief Psychotic Disorder | </i><i><b>1–6 Months</b></i><i> = Schizophreniform Disorder | </i><i><b>≥ 6 Months</b></i><i> = Schizophrenia | Psychosis + ≥ 2 weeks psychosis WITHOUT mood symptoms + major mood episode = </i><i><b>Schizoaffective Disorder</b></i><i>!)</i></p><h3><b>2. Etiology &amp; Rule-Out Workup</b></h3><ul>\n<li class=\"l1\"><b>Pathophysiology:</b> <mark class=\"hl rx\"><b>Dopamine Hypothesis</b></mark> (excess dopamine in <b>Mesolimbic pathway</b> -&gt; Positive symptoms; reduced dopamine in <b>Mesocortical pathway</b> -&gt; Negative symptoms!) + Genetic heritability (~80%) + Cannabis use in adolescence!</li>\n<li class=\"l1\"><b>Rule Out Secondary Psychosis FIRST:</b> <b>Urine Drug Screen</b> (Amphetamines, Cannabis, Synthetic cannabinoids [<i>Strox/Voodoo</i> in Egypt!], Hallucinogens), <mark class=\"hl mech\"><b>TSH</b></mark> , <mark class=\"hl mech\"><b>CBC/CMP</b></mark> , <b>Vitamin B12</b>, <b>HIV/Syphilis</b>, <mark class=\"hl mech\"><b>MRI Brain</b></mark> (first-episode psychosis -&gt; rule out tumor/autoimmune <b>NMDA-receptor encephalitis</b>!).</li>\n</ul><h3><b>3. Treatment</b></h3><ul>\n<li class=\"l1\"><b>First-Line Antipsychotics — Second-Generation (\"Atypical\") Antipsychotics (SGAs):</b> <b>Risperidone, Olanzapine, Quetiapine, Aripiprazole, Paliperidone, Ziprasidone</b> (block both <b>D2 + 5-HT2A</b> receptors -&gt; lower <b>EPS</b> [Extrapyramidal Symptoms] than First-Generation Antipsychotics [Haloperidol/Chlorpromazine], <i>but higher </i><i><b>Metabolic Syndrome</b></i><i> [weight gain, DM, dyslipidemia — worst with Olanzapine/Clozapine!]</i>).</li>\n<li class=\"l1\"><b>Acute Psychotic Agitation:</b> <b>IM Haloperidol + IM Lorazepam</b> (or <b>IM Olanzapine</b> — <i>never combine IM Olanzapine + IV/IM Benzodiazepine due to fatal respiratory depression!</i>).</li>\n<li class=\"l1\"><b>Treatment-Resistant Schizophrenia (Failed ≥ 2 Adequate Antipsychotic Trials):</b> <b>CLOZAPINE</b> (<b>MOST EFFECTIVE antipsychotic</b> and <b>reduces Suicide Risk</b> in schizophrenia — <i>requires weekly/biweekly </i><mark class=\"hl mech\"><i><b>ANC</b></i></mark><i> [Absolute Neutrophil Count] monitoring for </i><i><b>Agranulocytosis</b></i><i>!</i>).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u251\">← Case 19</button><button class=\"nv\" data-u=\"u253\">Case 21 →</button></nav></article><article class=\"view unit\" id=\"u253\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 21</span><h1>Delirium vs. Dementia (HOSPITAL CONFUSION APPROACH)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Delirium+vs.+Dementia+%28HOSPITAL+CONFUSION+APPROACH%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><b>Delirium</b> is an <b>ACUTE, FLUCTUATING</b> disturbance in <b>attention, awareness, and cognition</b> secondary to an underlying medical/toxic/metabolic insult (<b>MEDICAL EMERGENCY — High Inpatient Mortality!</b>).</p><h3><b>2. Crucial Bedside Comparison</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Delirium</b></p></th><th><p><b>Dementia</b></p></th></tr><tr><td><p><b>Onset &amp; Course</b></p></td><td><p><b>ACUTE</b> (hours–days); <b>FLUCTUATES</b> (\"sundowning\" worse at night!)</p></td><td><p><b>Insidious</b> (months–years); slowly progressive</p></td></tr><tr><td><p><b>Attention &amp; Consciousness</b></p></td><td><p><b>IMPAIRED</b> (easily distracted, altered alertness — hyperactive OR quiet hypoactive!)</p></td><td><p><b>Intact</b> until very late stage</p></td></tr><tr><td><p><b>Hallucinations</b></p></td><td><p><b>Visual hallucinations</b> common</p></td><td><p>Usually absent early (except <b>Lewy Body</b>!)</p></td></tr><tr><td><p><b>Reversibility</b></p></td><td><p><b>REVERSIBLE</b> if underlying medical cause treated!</p></td><td><p>Usually <b>Irreversible</b></p></td></tr></table><h3><b>3. Etiology of Delirium (Separated — Mnemonic: \"I WATCH DEATH\")</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>I</b>nfection (<b>UTI</b> &amp; <mark class=\"hl lab\"><b>Pneumonia</b></mark> = #1 causes in hospitalized elderly!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>W</b>ithdrawal (Alcohol, Benzodiazepines, Opioids).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>A</b>cute metabolic (<b>Hyponatremia</b>, Hypercalcemia, <b>Hypoglycemia</b>, Hypoxia, Hypercapnia, <mark class=\"hl lab\"><b>Uremia/Hepatic Encephalopathy</b></mark> ).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>T</b>rauma / <b>C</b>NS pathology (Subdural hematoma, Stroke, Seizures, Post-op).</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>D</b>rugs (<b>Anticholinergics</b>, <b>Benzodiazepines</b>, <b>Opioids</b>, <b>Steroids</b>, Polypharmacy!).</span></p>\n<p class=\"num\"><span class=\"n\">6.</span><span class=\"nt\"><b>F</b>ecal impaction &amp; <b>U</b>rinary retention (very frequently overlooked in elderly wards!).</span></p><h3><b>4. Management</b></h3><ul>\n<li class=\"l1\"><b>FIRST STEP:</b> <b>Identify and aggressively treat the underlying organic cause!</b> (Labs: CBC, CMP, Ca++, Glucose, Urinalysis, CXR, ECG, ABG, Medication review!).</li>\n<li class=\"l1\"><b>Non-Pharmacologic (First-Line for Agitation):</b> Reorientation (clock/calendar/glasses/hearing aids), family presence, natural light by day, quiet dark sleep at night, remove unnecessary catheters/restraints.</li>\n<li class=\"l1\"><b>Pharmacologic (ONLY if Severe Agitation Threatening Safety/Lines — Avoid Benzodiazepines Except in Alcohol/Benzo Withdrawal!):</b> Low-dose <b>Haloperidol </b>(0.5–1 mg) or <b>Quetiapine/Risperidone</b> (<i>check </i><i><b>QTc</b></i><i> first; AVOID in Parkinson’s/Lewy Body!</i>).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u252\">← Case 20</button><button class=\"nv\" data-u=\"u254\">Case 22 →</button></nav></article><article class=\"view unit\" id=\"u254\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 22</span><h1>Alcohol Withdrawal Syndrome, Delirium Tremens &amp; Wernicke-Korsakoff</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Alcohol+Withdrawal+Syndrome%2C+Delirium+Tremens+%26+Wernicke-Korsakoff\">🔍 Search on Google</a></header><h3><b>1. Alcohol Withdrawal Timeline (Hours After Last Drink!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>6 – 12 Hours (Minor Withdrawal):</b> Tremors (\"shakes\"), anxiety, tachycardia, diaphoresis, insomnia, GI upset.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>12 – 24 Hours (Alcoholic Hallucinosis):</b> Visual, tactile (\"bugs crawling\"), or auditory hallucinations with <b>INTACT orientation &amp; stable vitals</b>.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>12 – 48 Hours (Withdrawal Seizures):</b> Generalized tonic-clonic seizures (\"rum fits\").</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><mark class=\"hl lab\"><b>48 – 96 Hours (DELIRIUM TREMENS [DTs] — LIFE-THREATENING! 5–15% Mortality!):</b></mark> <b>Profound confusion/disorientation + Hallucinations + Severe Autonomic Instability (High fever, tachycardia &gt; 120, severe HTN, drenching sweats)!</b></span></p><h3><b>2. Treatment of Alcohol Withdrawal &amp; DTs</b></h3><ul>\n<li class=\"l1\"><b>DRUG OF CHOICE — BENZODIAZEPINES (Cross-tolerant with Alcohol at GABA-A receptors!):</b></li>\n<li class=\"l2\"><b>Lorazepam</b> (preferred in <mark class=\"hl lab\"><b>Liver Cirrhosis / Elderly</b></mark> — metabolized by glucuronidation <b>\"LOT\"</b>: <b>L</b>orazepam, <b>O</b>xazepam, <b>T</b>emazepam!) OR <b>Diazepam / Chlordiazepoxide</b> (longer half-life, smoother taper in healthy liver!).</li>\n<li class=\"l2\">Titrate using <b>CIWA-Ar Score</b> (symptom-triggered protocol; massive IV doses often needed in DTs!).</li>\n<li class=\"l1\"><b>MANDATORY NUTRITIONAL RULE:</b> Give <b>IV Thiamine (Vitamin B1 — 100–500 mg) BEFORE ANY IV GLUCOSE/DEXTROSE</b> + Folate + Multivitamins + Mg++/K+!</li>\n</ul><h3><b>3. Wernicke Encephalopathy vs. Korsakoff Syndrome (Thiamine [B1] Deficiency)</b></h3><ul>\n<li class=\"l1\"><b>Wernicke Encephalopathy (ACUTE — REVERSIBLE!):</b> Classic Triad (<b>\"CAN\"</b>): <b>C</b>onfusion (encephalopathy) + <b>A</b>taxia (wide-based gait) + <b>N</b>ystagmus / <b>O</b>phthalmoplegia (CN VI palsy) -&gt; Treat immediately with <b>High-Dose IV Thiamine (500 mg TID × 3 days)</b>!</li>\n<li class=\"l1\"><b>Korsakoff Syndrome (CHRONIC — LARGELY IRREVERSIBLE!):</b> Mammillary body &amp; dorsomedial thalamic damage -&gt; severe anterograde &amp; retrograde amnesia + <b>Confabulation</b> (making up stories to fill memory gaps!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u253\">← Case 21</button><button class=\"nv\" data-u=\"u255\">Case 23 →</button></nav></article><article class=\"view unit\" id=\"u255\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 23</span><h1>Opioid Overdose/withdrawal &amp; Tramadol / Benzodiazepine Misuse</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Opioid+Overdose%2Fwithdrawal+%26+Tramadol+%2F+Benzodiazepine+Misuse\">🔍 Search on Google</a></header><p><i>(Extremely relevant to Egyptian ERs — especially </i><i><b>Tramadol</b></i><i> and </i><i><b>Opioid</b></i><i> emergencies!)</i></p><h3><b>1. Acute Opioid Overdose (Classic Triad)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>CNS Depression</b> (stupor/coma).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Respiratory Depression (&lt; 8–12 breaths/min — #1 Cause of Death!)</b>.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Miosis (\"Pinpoint Pupils\")</b> <i>(Exception: Meperidine &amp; Tramadol may NOT always show pinpoint pupils; </i><i><b>Tramadol overdose uniquely causes SEIZURES + Serotonin Syndrome!</b></i><i>)</i>.</span></p>\n<ul>\n<li class=\"l1\"><b>Treatment:</b> <b>Airway/Bag-Valve-Mask Ventilation FIRST</b> -&gt; <b>IV/IN/IM Naloxone (0.4–2 mg, start 0.04–0.4 mg in chronic users to avoid violent acute withdrawal!)</b> -&gt; Repeat q2–3 min! <i>(Monitor ≥ 2–4 hrs after last Naloxone dose because Naloxone’s half-life [30–60 min] is SHORTER than most opioids/Methadone -&gt; risk of </i><i><b>re-sedation</b></i><i>!)</i></li>\n</ul><h3><b>2. Opioid Withdrawal (</b><b>\"Miserable, Flu-Like, NOT Life-Threatening!\"</b><b> — Unlike Alcohol/Benzo Withdrawal!)</b></h3><ul>\n<li class=\"l1\"><b>Signs:</b> Yawning, <b>lacrimation, rhinorrhea</b>, <b>mydriasis (dilated pupils!)</b>, piloerection (<b>\"cold turkey\"</b>), severe myalgias, abdominal cramps, vomiting/diarrhea, anxiety.</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Buprenorphine</b> (partial mu-agonist — start ONLY once moderate withdrawal begins to avoid precipitated withdrawal!) or <b>Methadone</b> (maintenance) + <b>Clonidine / Lofexidine</b> (autonomic symptoms) + Loperamide/Ondansetron/NSAIDs.</li>\n</ul><h3><b>3. Benzodiazepine Overdose &amp; Withdrawal</b></h3><ul>\n<li class=\"l1\"><b>Overdose:</b> Sedation, ataxia, slurred speech, normal/mildly depressed respiration (lethal if mixed with alcohol/opioids!). <i>Antidote:</i> <b>Flumazenil</b> (<i>USE WITH EXTREME CAUTION — CONTRAINDICATED in chronic Benzo users or TCA co-ingestion because it precipitates intractable fatal </i><i><b>Status Epilepticus</b></i><i>!</i>).</li>\n<li class=\"l1\"><b>Withdrawal (CAN BE FATAL Like Alcohol!):</b> Tremors, rebound anxiety, insomnia, <b>perceptual distortions, and life-threatening Seizures</b> -&gt; Manage with slow supervised <b>long-acting Diazepam/Clonazepam taper</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u254\">← Case 22</button><button class=\"nv\" data-u=\"u256\">Case 24 →</button></nav></article><article class=\"view unit\" id=\"u256\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 24</span><h1>Serotonin Syndrome vs. Neuroleptic Malignant Syndrome (NMS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Serotonin+Syndrome+vs.+Neuroleptic+Malignant+Syndrome+%28NMS%29\">🔍 Search on Google</a></header><p class=\"muted\"><i>(Two Potentially Fatal Drug-Induced Hyperthermic Emergencies — Frequently Tested &amp; Missed in ERs!)</i></p><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Serotonin Syndrome</b></p></th><th><p><b>Neuroleptic Malignant Syndrome (NMS)</b></p></th></tr><tr><td><p><b>Culprit Drugs</b></p></td><td><p>Combination of serotonergic drugs: <b>SSRIs/SNRIs + MAOIs, Tramadol, Linezolid, Triptans, Ondansetron, Dextromethorphan, MDMA</b></p></td><td><p><mark class=\"hl rx\"><b>Dopamine Antagonists:</b></mark> <b>First-Generation Antipsychotics (Haloperidol)</b> &gt; SGAs, <b>Metoclopramide</b>, OR <b>abrupt withdrawal of Levodopa</b>!</p></td></tr><tr><td><p><b>Onset</b></p></td><td><p><b>RAPID (&lt; 24 Hours — often within hours!)</b></p></td><td><p><b>GRADUAL (Days to Weeks)</b></p></td></tr><tr><td><p><b>Core Triad</b></p></td><td><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Mental Status Changes</b> (agitation, delirium)</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Autonomic Instability</b> (hyperthermia, tachycardia, HTN, diaphoresis)</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>NEUROMUSCULAR HYPEREXCITABILITY</b></span></p></td><td><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Mental Status Changes</b> (confusion, stupor)</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Autonomic Instability</b> (high fever &gt; 40°C, labile BP, tachycardia, diaphoresis)</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>SEVERE MUSCLE RIGIDITY</b></span></p></td></tr><tr><td><p><b>KEY EXAM DIFFERENTIATOR!</b></p></td><td><p><b>CLONUS (Inducible / Spontaneous / Ocular!) + HYPERREFLEXIA</b> (lower &gt; upper limbs) + Mydriasis + Hyperactive bowel sounds/diarrhea!</p></td><td><p><b>\"LEAD-PIPE\" RIGIDITY + HYPO/AREFLEXIA + BRADYREFLEXIA!</b> + <mark class=\"hl lab\"><b>Markedly Elevated CK (&gt; 1,000–10,000 U/L -&gt; Rhabdomyolysis/AKI!)</b></mark> + Leukocytosis!</p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p><b>STOP offending drugs</b> + IV fluids + Active cooling + <b>Benzodiazepines (Lorazepam/Diazepam)</b> + <b>Cyproheptadine</b> (5-HT2 antagonist)</p></td><td><p><b>STOP antipsychotic</b> + ICU + IV fluids (prevent rhabdomyolysis AKI!) + Active cooling + <b>Dantrolene</b> (muscle relaxant) + <b>Bromocriptine</b> (dopamine agonist) + Benzodiazepines</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u255\">← Case 23</button><button class=\"nv\" data-u=\"u257\">Case 25 →</button></nav></article><article class=\"view unit\" id=\"u257\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 25</span><h1>Somatic Symptom, Illness Anxiety &amp; Functional Neurological Disorder</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Somatic+Symptom%2C+Illness+Anxiety+%26+Functional+Neurological+Disorder\">🔍 Search on Google</a></header><h4><b>High-Yield Clinical Distinction (Always Rule Out Organic Disease First!)</b></h4><table class=\"t \"><tr class=\"hd\"><th><p><b>Disorder</b></p></th><th><p><b>Core Feature</b></p></th><th><p><b>Treatment</b></p></th></tr><tr><td><p><b>Somatic Symptom Disorder</b></p></td><td><p><b>≥ 1 distressing physical symptom(s)</b> (e.g., pain, fatigue) for &gt; 6 mos with <b>excessive disproportionate thoughts, anxiety, and time spent</b> on the symptoms</p></td><td><p><b>Regular scheduled brief visits</b> with ONE primary care doctor; validate pain, <b>avoid unnecessary tests/surgeries</b>, <b>CBT</b></p></td></tr><tr><td><p><b>Illness Anxiety Disorder</b> <i>(Hypochondriasis)</i></p></td><td><p>Preoccupation with <b>having or acquiring a serious illness </b>(cancer/HIV) with <b>NO or minimal somatic symptoms</b>; excessive health-checking or care-avoidance</p></td><td><p>Regular reassurance visits, <b>CBT</b>, SSRIs if severe</p></td></tr><tr><td><p><b>Functional Neurological Symptom (Conversion) Disorder</b></p></td><td><p>Sudden <b>neurological deficit</b> (blindness, paralysis, <b>psychogenic non-epileptic seizures [PNES]</b>) <b>incompatible with neuroanatomy</b>, often after acute stress (<b>\"La Belle Indifférence\"</b> — calm unconcern; <b>Hoover’s sign</b> (+) in functional leg weakness!)</p></td><td><p>Validate symptoms are real (brain software glitch, NOT malingering!), gentle reassurance of full recovery + <b>Physical Therapy + CBT</b>!</p></td></tr><tr><td><p><b>Factitious Disorder vs. Malingering</b></p></td><td><p><b>Factitious (Munchausen):</b> Consciously fakes/induces illness for <b>sick role/attention</b> (no money!). <b>Malingering:</b> Fakes illness for <b>external secondary gain</b> (avoid military/jail, get drugs/money)!</p></td><td><p>Gentle confrontation/psychiatry (Factitious); document objectively (Malingering)</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u256\">← Case 24</button><button class=\"nv\" data-u=\"u258\">Case 26 →</button></nav></article><article class=\"view unit\" id=\"u258\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 26</span><h1>Eating Disorders (ANOREXIA NERVOSA &amp; BULIMIA NERVOSA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Eating+Disorders+%28ANOREXIA+NERVOSA+%26+BULIMIA+NERVOSA%29\">🔍 Search on Google</a></header><h3><b>1. Comparison</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Anorexia Nervosa </b><i><b>(Highest Psychiatric Mortality!)</b></i></p></th><th><p><b>Bulimia Nervosa</b></p></th></tr><tr><td><p><b>BMI / Body Weight</b></p></td><td><p><b>Significantly LOW Body Weight (BMI &lt; 17–18.5 kg/m ²)</b> + intense fear of weight gain + distorted body image</p></td><td><p><b>Normal or slightly Overweight BMI!</b></p></td></tr><tr><td><p><b>Behaviors</b></p></td><td><p>Severe caloric restriction (Restricting vs. Binge-Purge subtype)</p></td><td><p>Recurrent <b>binge eating + compensatory purging</b> (vomiting, laxatives, diuretics, fasting) ≥ 1×/week × 3 mos</p></td></tr><tr><td><p><b>Classic Physical Signs</b></p></td><td><p>Amenorrhea, <b>lanugo hair</b>, <b>bradycardia, hypotension, hypothermia</b>, osteoporosis, <b>arrhythmias</b></p></td><td><p><b>Russell’s Sign</b> (calluses on knuckles!), <b>parotid gland hypertrophy</b>, <b>dental enamel erosion</b>!</p></td></tr><tr><td><p><b>Classic Labs</b></p></td><td><p>Leukopenia/anemia, elevated liver enzymes, low T3, <b>hypokalemia/alkalosis</b> (if purging)</p></td><td><p><b>Hypokalemic, Hypochloremic Metabolic Alkalosis</b> + elevated serum amylase (salivary)!</p></td></tr></table><h3><b>2. CRITICAL TREATMENT WARNING — REFEEDING SYNDROME</b></h3><ul>\n<li class=\"l1\">Rapidly refeeding a severely malnourished Anorexia patient triggers massive <b>insulin surge</b> -&gt; drives <b>Phosphate, Potassium, &amp; Magnesium</b> intracellularly -&gt; <b>Profound HYPOPHOSPHATEMIA (&lt; 1–2 mg/dL)</b> -&gt; <b>Rhabdomyolysis, Heart Failure, Arrhythmias, Seizures, Sudden Death!</b></li>\n<li class=\"l1\"><i>Prevention:</i> Start feeding <b>slowly</b> (1,000–1,200 kcal/day), give <b>Thiamine</b> first, and <b>aggressively monitor &amp; replete Phosphate, K+, and Mg++ daily</b>!</li>\n<li class=\"l1\"><i>Drugs:</i> <b>NO Fluoxetine/SSRIs</b> are proven effective for weight gain in Anorexia (relapse prevention once weight restored only; <b>Psychotherapy + Nutritional Rehab</b> = primary!). In <b>Bulimia:</b> <b>CBT + High-Dose Fluoxetine (60 mg/day)</b>! <i>(NEVER give </i><i><b>Bupropion</b></i><i> in Anorexia/Bulimia due to high </i><i><b>Seizure</b></i><i> risk!)</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u257\">← Case 25</button><button class=\"nv\" data-u=\"u259\">Case 27 →</button></nav></article><article class=\"view unit\" id=\"u259\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 27</span><h1>ADHD &amp; Autism Spectrum Disorder (CHILD &amp; ADOLESCENT PSYCHIATRY)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=ADHD+%26+Autism+Spectrum+Disorder+%28CHILD+%26+ADOLESCENT+PSYCHIATRY%29\">🔍 Search on Google</a></header><h3><b>A. ADHD (Attention-Deficit / Hyperactivity Disorder)</b></h3><ul>\n<li class=\"l1\"><b>Diagnosis:</b> Persistent symptoms of <b>Inattention</b> and/or <b>Hyperactivity-Impulsivity</b> starting <b>BEFORE age 12</b>, lasting <b>≥ 6 months</b>, and occurring in <b>≥ 2 settings</b> (e.g., BOTH home AND school!).</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\">&lt; 6 Years: <b>Behavioral Parent Training</b> (first-line).</li>\n<li class=\"l2\">≥ 6 Years: <b>Stimulants (Methylphenidate or Amphetamine salts)</b> = <b>First-Line &amp; Most Effective!</b> <i>(Side effects: decreased appetite/weight, insomnia, mild BP/HR rise, tics; check cardiac history before starting!)</i>. Non-stimulant alternatives: <b>Atomoxetine</b> (SNRI), <b>Guanfacine/Clonidine</b> (α2-agonists).</li>\n</ul><h3><b>B. Autism Spectrum Disorder (ASD)</b></h3><ul>\n<li class=\"l1\"><b>Core Dyad (Early Childhood Onset &lt; 3 Years):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\">Persistent deficits in <b>Social Communication &amp; Interaction</b> (poor eye contact, lack of joint attention/pointing by 12–18 mos, delayed speech, lack of social reciprocity).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Restricted, Repetitive Behaviors / Interests</b> (hand-flapping, echolalia, rigid adherence to routines, sensory hypersensitivity).</span></p>\n<ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Screen ALL Toddlers at 18 &amp; 24 Months</b></mark> (<b>M-CHAT</b>); do formal <b>Audiology Hearing Test</b> in every speech-delayed child!</li>\n<li class=\"l1\"><b>Treatment:</b> Early intensive <b>Behavioral / Speech / Occupational Therapy (ABA)</b>! <i>(Medications [</i><i><b>Risperidone / Aripiprazole</b></i><i>] treat ONLY severe irritability/aggression, NOT core ASD symptoms!)</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u258\">← Case 26</button><button class=\"nv\" data-u=\"u260\">Case 28 →</button></nav></article><article class=\"view unit\" id=\"u260\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 28</span><h1>Insomnia Disorder &amp; Parasomnias</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Insomnia+Disorder+%26+Parasomnias\">🔍 Search on Google</a></header><h3><b>1. Chronic Insomnia Disorder</b></h3><ul>\n<li class=\"l1\">Difficulty initiating/maintaining sleep ≥ 3 nights/week for <b>≥ 3 months</b> despite adequate sleep opportunity, causing daytime fatigue/impairment.</li>\n<li class=\"l1\"><b>FIRST-LINE TREATMENT (More Effective Long-Term Than Pills!):</b> <b>CBT-I (Cognitive Behavioral Therapy for Insomnia)</b> + <b>Sleep Hygiene</b> (fixed wake time, no screens/caffeine late, <b>use bed ONLY for sleep &amp; sex — leave bed if awake &gt; 20 min!</b>).</li>\n<li class=\"l1\"><b>Pharmacotherapy (Short-term adjunct only):</b> Melatonin / Ramelteon, <b>Zolpidem/Eszopiclone</b> (non-benzodiazepine Z-drugs — <i>warn about sleep-driving!</i>), <b>Suvorexant/Lemborexant</b> (Orexin antagonists), low-dose Doxepin/Trazodone. <i>(Avoid chronic Benzodiazepines/Antihistamines in elderly -&gt; falls &amp; delirium!)</i></li>\n</ul><h3><b>2. High-Yield Parasomnias &amp; Narcolepsy</b></h3><ul>\n<li class=\"l1\"><b>Night Terrors (NREM Stage N3 — Kids 3–12 yrs):</b> Child sits up screaming with autonomic surge (tachycardia/sweating), inconsolable, <b>NO memory next morning</b> -&gt; Benign, reassure parents, <b>DO NOT wake child!</b></li>\n<li class=\"l1\"><b>Nightmares (REM Sleep — Late night):</b> Vivid scary dreams, wakes fully alert, <b>vividly remembers dream</b>!</li>\n<li class=\"l1\"><b>REM Sleep Behavior Disorder (Older Adults):</b> <b>Loss of normal REM muscle atonia</b> -&gt; patient <b>physically acts out violent dreams</b> (punching/kicking bed partner!) -&gt; <b>Strong early predictor of Parkinson’s Disease / Lewy Body Dementia!</b> Treat with <b>Melatonin</b> or Clonazepam + safe bedroom!</li>\n<li class=\"l1\"><b>Narcolepsy (Hypocretin/Orexin Loss):</b> Excessive daytime sleepiness + <b>Cataplexy</b> (sudden loss of muscle tone triggered by laughter/emotion!) + <b>Sleep paralysis</b> + <b>Hypnagogic hallucinations</b> -&gt; Treat with <b>Modafinil</b> (daytime alertness) + <b>Sodium Oxybate / Venlafaxine</b> (cataplexy).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u259\">← Case 27</button><button class=\"nv\" data-u=\"u261\">Case 29 →</button></nav></article><article class=\"view unit\" id=\"u261\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 29</span><h1>Psychotropic Drug Toxicities &amp; Side Effects Mastery</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Psychotropic+Drug+Toxicities+%26+Side+Effects+Mastery\">🔍 Search on Google</a></header><h3><b>1. Extrapyramidal Symptoms (EPS) From Antipsychotics (Timeline &amp; Antidote!)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Reaction &amp; Timing</b></p></th><th><p><b>Clinical Features</b></p></th><th><p><b>Immediate Treatment</b></p></th></tr><tr><td><p><b>Acute Dystonia</b> <i>(Hours – Days)</i></p></td><td><p>Sudden painful involuntary muscle spasm: <b>oculogyric crisis</b> (eyes stuck upward), <b>torticollis</b>, opisthotonos, laryngospasm!</p></td><td><p><b>IM/IV Benztropine</b> or <b>Diphenhydramine</b> (or Biperiden) -&gt; rapid relief!</p></td></tr><tr><td><p><b>Akathisia</b> <i>(Days – Weeks — #1 Cause of Non-Compliance!)</i></p></td><td><p>Intense subjective <b>inner restlessness</b>, inability to sit still, constant pacing! <i>(Often misdiagnosed as worsening psychosis!)</i></p></td><td><p>Lower antipsychotic dose + <mark class=\"hl rx\"><b>Propranolol</b></mark> (First-line!) or <b>Lorazepam</b></p></td></tr><tr><td><p><b>Drug-Induced Parkinsonism</b> <i>(Weeks – Months)</i></p></td><td><p>Bradykinesia, shuffling gait, cogwheel rigidity, masked face</p></td><td><p>Switch to SGA (Quetiapine/Clozapine) or add <b>Benztropine / Trihexyphenidyl</b></p></td></tr><tr><td><p><b>Tardive Dyskinesia</b> <i>(Months – Years)</i></p></td><td><p><b>Irreversible</b> involuntary <b>lip-smacking, tongue-protruding, grimacing</b>, choreoathetoid movements!</p></td><td><p><b>Switch to Clozapine/Quetiapine</b> + <b>VMAT2 Inhibitors (Valbenazine / Deutetrabenazine)</b>! <i>(NOTE: Benztropine </i><i><b>WORSENS</b></i><i> Tardive Dyskinesia!)</i></p></td></tr></table><h3><b>2. Lithium Toxicity (</b><b>Narrow Therapeutic Index: 0.6 – 1.2 mEq/L; Toxic &gt; 1.5–2.0 mEq/L!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Triggers:</b> Dehydration, <mark class=\"hl lab\"><b>AKI</b></mark> , <mark class=\"hl rx\"><b>NSAIDs</b></mark> , <b>Thiazide Diuretics</b>, <mark class=\"hl rx\"><b>ACE-i / ARBs</b></mark> (all reduce renal Lithium clearance!).</li>\n<li class=\"l1\"><b>Signs:</b> Coarse tremor (mild is benign fine tremor), <b>ataxia, dysarthria</b>, nausea/vomiting/diarrhea, confusion, <b>hyperreflexia, seizures, coma</b>, <b>Nephrogenic Diabetes Insipidus</b> (polyuria), <mark class=\"hl lab\"><b>Hypothyroidism</b></mark> !</li>\n<li class=\"l1\"><b>Treatment:</b> Stop Lithium, aggressive <b>IV 0.9% Normal Saline</b> -&gt; <mark class=\"hl rx\"><b>Emergent Hemodialysis</b></mark> if Lithium <b>&gt; 4.0 mEq/L</b> (or &gt; 2.5 with severe neurotoxicity/AKI)! <i>(Remember </i><i><b>Ebstein’s Anomaly</b></i><i> if Lithium used in 1st trimester pregnancy!)</i></li>\n</ul><h3><b>3. TCA (Tricyclic Antidepressant — Amitriptyline) Overdose (\"3 Cs\": Convulsions, Coma, Cardiotoxicity!)</b></h3><ul>\n<li class=\"l1\"><b>Anticholinergic signs</b> (\"Hot as a hare, blind as a bat, dry as a bone, red as a beet, mad as a hatter\") + <b>QRS Widening (&gt; 100 ms -&gt; Ventricular Arrhythmias!)</b>.</li>\n<li class=\"l1\"><b>LIFE-SAVING ANTIDOTE:</b> <mark class=\"hl rx\"><b>IV SODIUM BICARBONATE (NaHCO3)</b></mark> bolus immediately if <b>QRS &gt; 100 ms</b> or arrhythmias/hypotension!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u260\">← Case 28</button><button class=\"nv\" data-u=\"u262\">Case 30 →</button></nav></article><article class=\"view unit\" id=\"u262\" hidden style=\"--c:#6a3fb5\"><button class=\"back\" data-p=\"10\">← Neurology &amp; Psychiatry</button><header class=\"uh\"><span class=\"ul\">Case 30</span><h1>Altered Mental Status (&quot;AEIOU-TIPS&quot;) ER Approach &amp; Brain Death</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Altered+Mental+Status+%28%22AEIOU-TIPS%22%29+ER+Approach+%26+Brain+Death\">🔍 Search on Google</a></header><h3><b>1. Rapid ER Approach to Coma / Altered Mental Status (\"AEIOU-TIPS\")</b></h3><ul>\n<li class=\"l1\"><b>A</b>lcohol / <b>A</b>cidosis (DKA)</li>\n<li class=\"l1\"><b>E</b>ndocrine (<b>Hypoglycemia!</b>, Thyroid storm/Myxedema, Adrenal crisis) / <b>E</b>lectrolytes (<b>Hyponatremia</b>, Hypercalcemia, Hyperammonemia)</li>\n<li class=\"l1\"><b>I</b>nfection (<mark class=\"hl lab\"><b> Meningitis, Encephalitis, Sepsis</b></mark> — elderly UTI/Pneumonia!)</li>\n<li class=\"l1\"><b>O</b>verdose / <b>O</b>xygen (<b>Hypoxia, Hypercapnia [CO2 narcosis], CO poisoning, Opioids/Benzos</b>)</li>\n<li class=\"l1\"><b>U</b>remia (Renal failure)</li>\n<li class=\"l1\"><b>T</b>rauma (EDH, SDH, diffuse axonal injury) / <b>T</b>emperature (Hypo/Hyperthermia)</li>\n<li class=\"l1\"><b>I</b>nsulin (Hypo/Hyperglycemia)</li>\n<li class=\"l1\"><b>P</b>sychiatric / <b>P</b>oisons</li>\n<li class=\"l1\"><b>S</b>troke (<b>Basilar/Pontine stroke</b>, SAH, ICH) / <b>S</b>eizure (<b>Non-convulsive Status Epilepticus</b> / Post-ictal!)</li>\n</ul><h3><b>2. ER First 5 Minutes (\"Coma Cocktail\" Modified!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>ABCDEs</b> (Intubate if GCS ≤ 8 or unable to protect airway; C-spine precautions if trauma!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>STAT Fingerstick Blood Glucose</b> (give <mark class=\"hl rx\"><b>IV D50W 50 mL</b></mark> immediately if &lt; 70 mg/dL — precede with <b>IV Thiamine 100 mg</b> if malnourished/alcoholic!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>IV Naloxone</b> if pinpoint pupils/respiratory depression.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>STAT Non-Contrast CT Brain</b> + <mark class=\"hl mech\"><b>ABG, Electrolytes, CBC, RFTs, LFTs, Ammonia, Cultures, ECG</b></mark> !</span></p><h3><b>3. Brain Death Determination (3 Essential Prerequisites + 3 Clinical Pillars)</b></h3><ul>\n<li class=\"l1\"><b>Prerequisites (MUST Exclude Mimics FIRST!):</b> Known irreversible catastrophic brain injury + <b>NO hypothermia (core temp &gt; 36°C)</b>, <mark class=\"hl lab\"><b>NO severe hypotension (SBP ≥ 100)</b></mark> , <b>NO sedatives/paralytics/metabolic coma</b>!</li>\n<li class=\"l1\"><b>3 Diagnostic Findings:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Coma:</b> Complete unresponsiveness to maximal painful stimuli (cerebral origin — spinal reflexes may persist!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Absent ALL Brainstem Reflexes:</b></mark> Fixed dilated/mid-position pupils (no light reflex), absent corneal, oculocephalic (\"doll’s eyes\"), oculovestibular (cold caloric!), gag, and cough reflexes!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Positive Apnea Test:</b> Pre-oxygenate 100% O2 -&gt; disconnect ventilator with O2 catheter in trachea -&gt; <b>NO spontaneous respiratory effort</b> despite <b>PaCO2 rising ≥ 60 mmHg</b> (or ≥ 20 mmHg above baseline)! <i>(Confirm with Cerebral Angiography / EEG / Nuclear flow scan ONLY if clinical apnea/exam cannot be completed!)</i></span></p>\n<p class=\"muted\"><i>End of Part 10B — Neurology &amp; Psychiatry (30 Cases Complete!).</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u261\">← Case 29</button></nav></article>"});
